// Python-style exceptions.
//
// The reference script lets any exception raised by eval()/yaml.dump() escape,
// which makes CPython print a traceback and exit with status 1.  We model the
// exception type name so the diagnostic we print resembles Python's.

export class PyError extends Error {
  constructor(type, text) {
    super(type + ': ' + text);
    this.pyType = type;
    this.pyText = text;
  }

  // "NameError: name 'x' is not defined"
  format() {
    return this.pyText ? this.pyType + ': ' + this.pyText : this.pyType;
  }
}

export function syntaxError(text) {
  return new PyError('SyntaxError', text || 'invalid syntax');
}

export function nameError(name) {
  return new PyError('NameError', "name '" + name + "' is not defined");
}

export function typeError(text) {
  return new PyError('TypeError', text);
}

export function valueError(text) {
  return new PyError('ValueError', text);
}

export function keyError(text) {
  return new PyError('KeyError', text);
}

export function indexError(text) {
  return new PyError('IndexError', text);
}

export function attributeError(text) {
  return new PyError('AttributeError', text);
}

export function zeroDivisionError(text) {
  return new PyError('ZeroDivisionError', text);
}

export function overflowError(text) {
  return new PyError('OverflowError', text);
}

export function notSupported(what) {
  return new PyError('NotImplementedError', what + ' is not supported');
}

