// repr()/str() of a Python float.
//
// CPython prints the shortest decimal string that round-trips, using
// positional notation while -4 < decpt <= 16 and scientific notation
// otherwise (decpt is the position of the decimal point: value =
// 0.d1d2... * 10**decpt).  Positional output always keeps a ".0" tail so the
// result still looks like a float, while scientific output does not, and the
// exponent is padded to at least two digits.

// Shortest round-tripping digit string of a positive finite float, together
// with its scientific exponent (value = d.ddd * 10**exp).
function shortestDigits(x) {
  const s = x.toExponential(); // shortest form that uniquely identifies x
  const ePos = s.indexOf('e');
  const mantissa = s.slice(0, ePos);
  const exp = Number(s.slice(ePos + 1));
  const dot = mantissa.indexOf('.');
  const digits = dot < 0 ? mantissa : mantissa.slice(0, dot) + mantissa.slice(dot + 1);
  return { digits, exp };
}

function zeros(n) {
  let out = '';
  for (let i = 0; i < n; i++) out += '0';
  return out;
}

export function floatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';

  const negative = x < 0 || Object.is(x, -0);
  const magnitude = negative ? -x : x;
  let body;

  if (magnitude === 0) {
    body = '0.0';
  } else {
    const { digits, exp } = shortestDigits(magnitude);
    const decpt = exp + 1;
    if (decpt <= -4 || decpt > 16) {
      const mantissa = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
      const sign = exp < 0 ? '-' : '+';
      let power = String(exp < 0 ? -exp : exp);
      if (power.length < 2) power = '0' + power;
      body = mantissa + 'e' + sign + power;
    } else if (decpt <= 0) {
      body = '0.' + zeros(-decpt) + digits;
    } else if (decpt >= digits.length) {
      body = digits + zeros(decpt - digits.length) + '.0';
    } else {
      body = digits.slice(0, decpt) + '.' + digits.slice(decpt);
    }
  }
  return negative ? '-' + body : body;
}

