// The Python object model, mapped onto JavaScript values.
//
//   Python int   -> JS bigint      (arbitrary precision, like CPython)
//   Python float -> JS number
//   Python bool  -> JS boolean
//   Python None  -> JS null
//   Python str   -> JS string
//   everything else -> one of the wrapper classes below
//
// Wrappers keep list/tuple and set/frozenset distinguishable, which matters
// because PyYAML emits a different tag for each of them.

import { typeError, indexError } from './errors.mjs';

export class PyList {
  constructor(items) { this.items = items || []; }
}

export class PyTuple {
  constructor(items) { this.items = items || []; }
}

// Insertion-ordered mapping keyed by Python hash/equality semantics.
export class PyDict {
  constructor() { this.slots = new Map(); } // hash key -> [key, value]

  get size() { return this.slots.size; }

  has(key) { return this.slots.has(hashKey(key)); }

  get(key) {
    const slot = this.slots.get(hashKey(key));
    return slot === undefined ? undefined : slot[1];
  }

  // CPython keeps the first key ever stored and only replaces the value.
  set(key, value) {
    const id = hashKey(key);
    const slot = this.slots.get(id);
    if (slot === undefined) this.slots.set(id, [key, value]);
    else slot[1] = value;
  }

  delete(key) { return this.slots.delete(hashKey(key)); }

  entries() { return Array.from(this.slots.values()); }

  keys() { return this.entries().map((entry) => entry[0]); }

  values() { return this.entries().map((entry) => entry[1]); }
}

class PyAbstractSet {
  constructor() { this.slots = new Map(); } // hash key -> element

  get size() { return this.slots.size; }

  has(value) { return this.slots.has(hashKey(value)); }

  add(value) {
    const id = hashKey(value);
    if (!this.slots.has(id)) this.slots.set(id, value);
  }

  delete(value) { return this.slots.delete(hashKey(value)); }

  elements() { return Array.from(this.slots.values()); }
}

export class PySet extends PyAbstractSet {}
export class PyFrozenSet extends PyAbstractSet {}

export class PyBytes {
  constructor(data) { this.data = data instanceof Uint8Array ? data : new Uint8Array(data); }
}

export class PyComplex {
  constructor(re, im) { this.re = re; this.im = im; }
}

export class PyRange {
  constructor(start, stop, step) { this.start = start; this.stop = stop; this.step = step; }

  toArray() {
    const out = [];
    const { start, stop, step } = this;
    if (step > 0n) for (let i = start; i < stop; i += step) out.push(i);
    else for (let i = start; i > stop; i += step) out.push(i);
    return out;
  }
}

// A materialised generator/iterator: comprehensions and zip()/map() produce
// these.  Only ever consumed as an iterable, never dumped in practice.
export class PyIterator {
  constructor(items) { this.items = items || []; }
}

export class PyBuiltin {
  constructor(name, call) { this.name = name; this.call = call; }
}

export class PyBoundMethod {
  constructor(name, owner, call) { this.name = name; this.owner = owner; this.call = call; }
}

export class PyFunction {
  constructor(params, body, env) { this.params = params; this.body = body; this.env = env; }
}

// Result of type(x); PyYAML dumps it as !!python/name:builtins.<name>.
export class PyTypeRef {
  constructor(name) { this.name = name; }
}

export const isInt = (v) => typeof v === 'bigint';
export const isFloat = (v) => typeof v === 'number';
export const isBool = (v) => typeof v === 'boolean';
export const isStr = (v) => typeof v === 'string';
export const isNone = (v) => v === null;
export const isNumber = (v) => isInt(v) || isFloat(v) || isBool(v);

// Python str is a sequence of code points, not UTF-16 units.
export function chars(s) { return Array.from(s); }

export function strLength(s) {
  let n = 0;
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff && i + 1 < s.length) {
      const next = s.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) i++;
    }
    n++;
  }
  return n;
}

export function typeName(v) {
  if (v === null) return 'NoneType';
  switch (typeof v) {
    case 'bigint': return 'int';
    case 'number': return 'float';
    case 'boolean': return 'bool';
    case 'string': return 'str';
    default: break;
  }
  if (v instanceof PyList) return 'list';
  if (v instanceof PyTuple) return 'tuple';
  if (v instanceof PyDict) return 'dict';
  if (v instanceof PySet) return 'set';
  if (v instanceof PyFrozenSet) return 'frozenset';
  if (v instanceof PyBytes) return 'bytes';
  if (v instanceof PyComplex) return 'complex';
  if (v instanceof PyRange) return 'range';
  if (v instanceof PyIterator) return 'generator';
  if (v instanceof PyBuiltin || v instanceof PyBoundMethod) return 'builtin_function_or_method';
  if (v instanceof PyFunction) return 'function';
  if (v instanceof PyTypeRef) return 'type';
  return 'object';
}

// Key used for dict/set lookups.  Numbers that compare equal must share a key
// (hash(1) == hash(1.0) == hash(True)), and mutable containers are unhashable.
export function hashKey(v) {
  if (v === null) return 'N';
  if (v === true) return 'i1';
  if (v === false) return 'i0';
  switch (typeof v) {
    case 'bigint': return 'i' + v.toString();
    case 'string': return 's' + v;
    case 'number':
      if (Number.isFinite(v) && Number.isInteger(v)) return 'i' + BigInt(v).toString();
      if (Number.isNaN(v)) return 'fnan';
      return 'f' + v;
    default: break;
  }
  if (v instanceof PyTuple) return 't(' + v.items.map(hashKey).join(',') + ')';
  if (v instanceof PyFrozenSet) return 'fs(' + v.elements().map(hashKey).sort().join(',') + ')';
  if (v instanceof PyBytes) {
    let out = 'b';
    for (const byte of v.data) out += byte.toString(16).padStart(2, '0');
    return out;
  }
  if (v instanceof PyComplex) return 'c' + v.re + ',' + v.im;
  if (v instanceof PyRange) return 'r' + v.start + ',' + v.stop + ',' + v.step;
  if (v instanceof PyTypeRef) return 'T' + v.name;
  throw typeError("unhashable type: '" + typeName(v) + "'");
}

// Truthiness.
export function isTruthy(v) {
  if (v === null || v === false) return false;
  if (v === true) return true;
  switch (typeof v) {
    case 'bigint': return v !== 0n;
    case 'number': return v !== 0;
    case 'string': return v.length > 0;
    default: break;
  }
  if (v instanceof PyList || v instanceof PyTuple || v instanceof PyIterator) return v.items.length > 0;
  if (v instanceof PyDict) return v.size > 0;
  if (v instanceof PyAbstractSet) return v.size > 0;
  if (v instanceof PyBytes) return v.data.length > 0;
  if (v instanceof PyComplex) return v.re !== 0 || v.im !== 0;
  if (v instanceof PyRange) return v.toArray().length > 0;
  return true;
}

// Sequence of elements for iteration; throws for non-iterables.
export function iterate(v) {
  if (typeof v === 'string') return chars(v);
  if (v instanceof PyList || v instanceof PyTuple || v instanceof PyIterator) return v.items.slice();
  if (v instanceof PyDict) return v.keys();
  if (v instanceof PyAbstractSet) return v.elements();
  if (v instanceof PyRange) return v.toArray();
  if (v instanceof PyBytes) return Array.from(v.data, (byte) => BigInt(byte));
  throw typeError("'" + typeName(v) + "' object is not iterable");
}

// Normalises a Python index (negative counts from the end).
export function normalizeIndex(index, length, what) {
  let i = Number(index);
  if (i < 0) i += length;
  if (i < 0 || i >= length) throw indexError(what + ' index out of range');
  return i;
}

