// Python comparison, equality and repr()/str() rendering.

import { typeError } from './errors.mjs';
import { floatRepr } from './floatrepr.mjs';
import {
  PyList, PyTuple, PyDict, PySet, PyFrozenSet, PyBytes, PyComplex, PyRange,
  PyIterator, PyTypeRef, PyBuiltin, PyBoundMethod, PyFunction,
  isNumber, typeName, chars,
} from './values.mjs';

function numeric(v) {
  if (v === true) return 1n;
  if (v === false) return 0n;
  return v;
}

// Code-point ordering, which is what CPython uses for str comparison
// (JS "<" would compare UTF-16 units instead).
function compareStrings(a, b) {
  const left = chars(a);
  const right = chars(b);
  const shared = Math.min(left.length, right.length);
  for (let i = 0; i < shared; i++) {
    const x = left[i].codePointAt(0);
    const y = right[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  if (left.length === right.length) return 0;
  return left.length < right.length ? -1 : 1;
}

function compareBytes(a, b) {
  const shared = Math.min(a.length, b.length);
  for (let i = 0; i < shared; i++) {
    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
  }
  if (a.length === b.length) return 0;
