  ['a', '\x07'], ['b', '\b'], ['f', '\f'], ['v', '\v'], ['0', '\0'],
]);

// Interprets the escape sequences of a non-raw str literal.
export function decodeEscapes(raw) {
  let out = '';
  let i = 0;
  while (i < raw.length) {
    const ch = raw[i];
    if (ch !== '\\') {
      out += ch;
      i++;
      continue;
    }
    const next = raw[i + 1];
    if (next === undefined) throw syntaxError('EOL while scanning string literal');
    if (next === '\n') {
      i += 2;
      continue;
    }
    if (next === 'x' || next === 'u' || next === 'U') {
      const width = next === 'x' ? 2 : next === 'u' ? 4 : 8;
      const digits = raw.slice(i + 2, i + 2 + width);
      let valid = digits.length === width;
      if (valid) for (const digit of digits) if (!isHex(digit)) valid = false;
      if (!valid) throw syntaxError('truncated escape sequence');
      out += String.fromCodePoint(parseInt(digits, 16));
      i += 2 + width;
      continue;
    }
    if (isOctal(next)) {
      let digits = '';
      let j = i + 1;
      while (j < raw.length && digits.length < 3 && isOctal(raw[j])) {
        digits += raw[j];
        j++;
      }
      out += String.fromCharCode(parseInt(digits, 8));
      i = j;
      continue;
    }
    const simple = SIMPLE_ESCAPES.get(next);
    if (simple !== undefined) {
      out += simple;
      i += 2;
      continue;
    }
    out += ch + next; // unknown escapes stay verbatim, like CPython
    i += 2;
  }
  return out;
}

// bytes literals: every code unit must be < 256 once escapes are resolved.
function decodeBytes(raw, isRaw) {
  const text = isRaw ? raw : decodeEscapes(raw);
  const out = [];
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    if (code > 0xff) {
      // Non-ASCII source characters are invalid in bytes literals; encode as
      // UTF-8 so we degrade gracefully instead of losing data.
      const encoded = new TextEncoder().encode(text[i]);
      for (const byte of encoded) out.push(byte);
    } else {
      out.push(code);
    }
  }
  return Uint8Array.from(out);
}

