// Recursive-descent parser producing an AST for the Python expression
// grammar, following CPython's operator precedence.

import { syntaxError } from './errors.mjs';
import { Tokenizer, TOKEN } from './tokenizer.mjs';

const KEYWORDS = new Set([
  'and', 'or', 'not', 'in', 'is', 'if', 'else', 'for', 'lambda', 'None',
  'True', 'False',
]);

const COMPARISON_OPS = new Set(['<', '>', '<=', '>=', '==', '!=']);

export class Parser {
  constructor(source) {
    this.tokens = new Tokenizer(source).tokenize();
    this.index = 0;
  }

  get current() { return this.tokens[this.index]; }

  error() { throw syntaxError('invalid syntax'); }

  advance() { return this.tokens[this.index++]; }

  atOp(value) {
    const token = this.current;
    return token.type === TOKEN.OP && token.value === value;
  }

  atName(value) {
    const token = this.current;
    return token.type === TOKEN.NAME && token.value === value;
  }

  eatOp(value) {
    if (!this.atOp(value)) return false;
    this.index++;
    return true;
  }

  eatName(value) {
    if (!this.atName(value)) return false;
    this.index++;
    return true;
  }

  expectOp(value) {
    if (!this.eatOp(value)) this.error();
  }

  // Entry point: a whole eval() input, which may be a bare tuple ("1, 2").
  parseProgram() {
    if (this.current.type === TOKEN.EOF) this.error();
    const node = this.parseExpressionList();
    if (this.current.type !== TOKEN.EOF) this.error();
    return node;
  }

  parseExpressionList() {
    const first = this.parseExpression();
    if (!this.atOp(',')) return first;
    const elements = [first];
    while (this.eatOp(',')) {
      if (this.current.type === TOKEN.EOF) break;
      elements.push(this.parseExpression());
    }
    return { type: 'Tuple', elements };
  }

  parseExpression() {
    if (this.atName('lambda')) return this.parseLambda();
    const body = this.parseOrTest();
    if (this.atName('if')) {
      // Conditional expression: "a if cond else b".
      const save = this.index;
      this.index++;
      const test = this.parseOrTest();
      if (!this.eatName('else')) {
        this.index = save;
        return body;
      }
      const orElse = this.parseExpression();
      return { type: 'IfExp', test, body, orElse };
    }
    return body;
  }

  parseLambda() {
    this.eatName('lambda');
    const params = [];
    while (!this.atOp(':')) {
      const token = this.advance();
      if (token.type !== TOKEN.NAME) this.error();
      let fallback = null;
      if (this.eatOp('=')) fallback = this.parseExpression();
      params.push({ name: token.value, fallback });
      if (!this.eatOp(',')) break;
    }
    this.expectOp(':');
    const body = this.parseExpression();
    return { type: 'Lambda', params, body };
  }

  parseOrTest() {
    let node = this.parseAndTest();
    while (this.atName('or')) {
      this.index++;
      node = { type: 'BoolOp', op: 'or', left: node, right: this.parseAndTest() };
    }
    return node;
  }

  parseAndTest() {
    let node = this.parseNotTest();
    while (this.atName('and')) {
      this.index++;
      node = { type: 'BoolOp', op: 'and', left: node, right: this.parseNotTest() };
    }
    return node;
  }

  parseNotTest() {
    if (this.atName('not')) {
      this.index++;
      return { type: 'UnaryOp', op: 'not', operand: this.parseNotTest() };
    }
    return this.parseComparison();
  }

  parseComparison() {
    const left = this.parseBitOr();
    const ops = [];
    const operands = [];
    for (;;) {
      let op = null;
      if (this.current.type === TOKEN.OP && COMPARISON_OPS.has(this.current.value)) {
        op = this.advance().value;
      } else if (this.atName('in')) {
        this.index++;
        op = 'in';
      } else if (this.atName('not') && this.tokens[this.index + 1].type === TOKEN.NAME
          && this.tokens[this.index + 1].value === 'in') {
        this.index += 2;
        op = 'not in';
      } else if (this.atName('is')) {
        this.index++;
        op = this.eatName('not') ? 'is not' : 'is';
      } else {
        break;
      }
      ops.push(op);
      operands.push(this.parseBitOr());
    }
    if (ops.length === 0) return left;
    return { type: 'Compare', left, ops, operands };
  }

  parseBinary(operators, next) {
    let node = next.call(this);
    while (this.current.type === TOKEN.OP && operators.has(this.current.value)) {
      const op = this.advance().value;
      node = { type: 'BinOp', op, left: node, right: next.call(this) };
    }
    return node;
  }

  parseBitOr() { return this.parseBinary(new Set(['|']), this.parseBitXor); }

  parseBitXor() { return this.parseBinary(new Set(['^']), this.parseBitAnd); }

  parseBitAnd() { return this.parseBinary(new Set(['&']), this.parseShift); }

  parseShift() { return this.parseBinary(new Set(['<<', '>>']), this.parseArith); }

  parseArith() { return this.parseBinary(new Set(['+', '-']), this.parseTerm); }

  parseTerm() {
    return this.parseBinary(new Set(['*', '/', '//', '%', '@']), this.parseFactor);
  }

  parseFactor() {
    if (this.current.type === TOKEN.OP) {
      const op = this.current.value;
      if (op === '+' || op === '-' || op === '~') {
        this.index++;
        return { type: 'UnaryOp', op, operand: this.parseFactor() };
      }
    }
    return this.parsePower();
  }

  parsePower() {
    const base = this.parseAtomWithTrailers();
    if (this.eatOp('**')) {
      return { type: 'BinOp', op: '**', left: base, right: this.parseFactor() };
    }
    return base;
  }

  parseAtomWithTrailers() {
    let node = this.parseAtom();
    for (;;) {
      if (this.atOp('(')) {
        node = this.parseCall(node);
      } else if (this.atOp('[')) {
        this.index++;
        const slice = this.parseSubscript();
        this.expectOp(']');
        node = { type: 'Subscript', value: node, slice };
      } else if (this.atOp('.')) {
        this.index++;
        const token = this.advance();
        if (token.type !== TOKEN.NAME) this.error();
        node = { type: 'Attribute', value: node, attr: token.value };
      } else {
        return node;
      }
    }
  }

  parseCall(func) {
    this.expectOp('(');
    const args = [];
    const keywords = [];
    while (!this.atOp(')')) {
      if (this.eatOp('**')) {
        keywords.push({ name: null, value: this.parseExpression() });
      } else if (this.eatOp('*')) {
        args.push({ type: 'Starred', value: this.parseExpression() });
      } else if (this.current.type === TOKEN.NAME && !KEYWORDS.has(this.current.value)
          && this.tokens[this.index + 1].type === TOKEN.OP
          && this.tokens[this.index + 1].value === '=') {
        const name = this.advance().value;
        this.index++;
        keywords.push({ name, value: this.parseExpression() });
      } else {
        const value = this.parseExpression();
        if (this.atName('for')) {
          args.push({ type: 'GeneratorExp', element: value, clauses: this.parseComprehension() });
        } else {
          args.push(value);
        }
      }
      if (!this.eatOp(',')) break;
    }
    this.expectOp(')');
    return { type: 'Call', func, args, keywords };
  }

  parseSubscript() {
    const parts = [];
    let sawColon = false;
    let element = this.atOp(':') ? null : this.parseExpression();
    parts.push(element);
    while (this.eatOp(':')) {
      sawColon = true;
      if (this.atOp(']') || this.atOp(':')) parts.push(null);
      else parts.push(this.parseExpression());
    }
    if (!sawColon) {
      // Possibly a tuple index: a[1, 2]
      if (this.atOp(',')) {
        const elements = [parts[0]];
        while (this.eatOp(',')) {
          if (this.atOp(']')) break;
          elements.push(this.parseExpression());
        }
        return { type: 'Tuple', elements };
      }
      if (parts[0] === null) this.error();
      return parts[0];
    }
    return {
      type: 'Slice',
      lower: parts[0] || null,
      upper: parts.length > 1 ? parts[1] : null,
      step: parts.length > 2 ? parts[2] : null,
    };
  }

  // "for target in iterable [if cond]*" clauses of a comprehension.
  parseComprehension() {
    const clauses = [];
    while (this.atName('for')) {
      this.index++;
      const target = this.parseTargetList();
      if (!this.eatName('in')) this.error();
      const iterable = this.parseOrTest();
      const conditions = [];
      while (this.atName('if')) {
        this.index++;
        conditions.push(this.parseOrTest());
      }
      clauses.push({ target, iterable, conditions });
    }
    if (clauses.length === 0) this.error();
    return clauses;
  }

  parseTargetList() {
    const targets = [this.parseTarget()];
    while (this.atOp(',')) {
      this.index++;
      if (this.atName('in')) break;
      targets.push(this.parseTarget());
    }
    if (targets.length === 1) return targets[0];
    return { type: 'TupleTarget', elements: targets };
  }

  parseTarget() {
    if (this.eatOp('(') || this.eatOp('[')) {
      const closing = this.tokens[this.index - 1].value === '(' ? ')' : ']';
      const targets = [];
      while (!this.atOp(closing)) {
        targets.push(this.parseTarget());
        if (!this.eatOp(',')) break;
      }
      this.expectOp(closing);
      return { type: 'TupleTarget', elements: targets };
    }
    const token = this.advance();
    if (token.type !== TOKEN.NAME || KEYWORDS.has(token.value)) this.error();
    return { type: 'NameTarget', name: token.value };
  }

  parseAtom() {
    const token = this.current;
    if (token.type === TOKEN.NUMBER) {
      this.index++;
      if (token.imaginary) return { type: 'Imaginary', value: token.value };
      return { type: 'Constant', value: token.value };
    }
    if (token.type === TOKEN.STRING || token.type === TOKEN.BYTES || token.type === TOKEN.FSTRING) {
      return this.parseStringGroup();
    }
    if (token.type === TOKEN.NAME) {
      if (token.value === 'None') { this.index++; return { type: 'Constant', value: null }; }
      if (token.value === 'True') { this.index++; return { type: 'Constant', value: true }; }
      if (token.value === 'False') { this.index++; return { type: 'Constant', value: false }; }
      if (token.value === 'lambda') return this.parseLambda();
      if (token.value === 'not') return this.parseNotTest();
      if (KEYWORDS.has(token.value)) this.error();
      this.index++;
      return { type: 'Name', name: token.value };
    }
    if (token.type === TOKEN.OP) {
      if (token.value === '(') return this.parseParenthesised();
      if (token.value === '[') return this.parseListDisplay();
      if (token.value === '{') return this.parseBraceDisplay();
      if (token.value === '...') { this.index++; return { type: 'Ellipsis' }; }
    }
    this.error();
    return null;
  }

  // Adjacent string literals concatenate; f-strings make the whole group one
  // formatted string.
  parseStringGroup() {
    const parts = [];
    let hasFormat = false;
    let hasBytes = false;
    let hasText = false;
    while (this.current.type === TOKEN.STRING || this.current.type === TOKEN.BYTES
        || this.current.type === TOKEN.FSTRING) {
      const token = this.advance();
      if (token.type === TOKEN.BYTES) {
        hasBytes = true;
        parts.push({ kind: 'bytes', value: token.value });
      } else if (token.type === TOKEN.FSTRING) {
        hasFormat = true;
        hasText = true;
        parts.push({ kind: 'fstring', value: token.value, raw: token.raw });
      } else {
        hasText = true;
        parts.push({ kind: 'str', value: token.value });
      }
    }
    if (hasBytes && hasText) this.error();
    if (hasBytes) {
      const chunks = [];
      for (const part of parts) for (const byte of part.value.data) chunks.push(byte);
      return { type: 'Constant', value: new (parts[0].value.constructor)(Uint8Array.from(chunks)) };
    }
    if (!hasFormat) {
      return { type: 'Constant', value: parts.map((part) => part.value).join('') };
    }
    const pieces = [];
    for (const part of parts) {
      if (part.kind === 'str') pieces.push({ kind: 'text', text: part.value });
      else for (const piece of parseFString(part.value, part.raw)) pieces.push(piece);
    }
    return { type: 'FormattedString', pieces };
  }

  parseParenthesised() {
    this.expectOp('(');
    if (this.eatOp(')')) return { type: 'Tuple', elements: [] };
    const first = this.parseExpression();
    if (this.atName('for')) {
      const clauses = this.parseComprehension();
      this.expectOp(')');
      return { type: 'GeneratorExp', element: first, clauses };
    }
    if (this.atOp(',')) {
      const elements = [first];
      while (this.eatOp(',')) {
        if (this.atOp(')')) break;
        elements.push(this.parseExpression());
      }
      this.expectOp(')');
      return { type: 'Tuple', elements };
    }
    this.expectOp(')');
    return first;
  }

  parseListDisplay() {
    this.expectOp('[');
    if (this.eatOp(']')) return { type: 'List', elements: [] };
    const first = this.parseStarOrExpression();
    if (this.atName('for')) {
      const clauses = this.parseComprehension();
      this.expectOp(']');
      return { type: 'ListComp', element: first, clauses };
    }
    const elements = [first];
    while (this.eatOp(',')) {
      if (this.atOp(']')) break;
      elements.push(this.parseStarOrExpression());
    }
    this.expectOp(']');
    return { type: 'List', elements };
  }

  parseBraceDisplay() {
    this.expectOp('{');
    if (this.eatOp('}')) return { type: 'Dict', keys: [], values: [] };
    if (this.atOp('**')) {
      this.index++;
      const keys = [null];
      const values = [this.parseOrTest()];
      while (this.eatOp(',')) {
        if (this.atOp('}')) break;
        if (this.eatOp('**')) {
          keys.push(null);
          values.push(this.parseOrTest());
        } else {
          const key = this.parseExpression();
          this.expectOp(':');
          keys.push(key);
          values.push(this.parseExpression());
        }
      }
      this.expectOp('}');
      return { type: 'Dict', keys, values };
    }
    const first = this.parseStarOrExpression();
    if (this.eatOp(':')) {
      const firstValue = this.parseExpression();
      if (this.atName('for')) {
        const clauses = this.parseComprehension();
        this.expectOp('}');
        return { type: 'DictComp', key: first, value: firstValue, clauses };
      }
      const keys = [first];
      const values = [firstValue];
      while (this.eatOp(',')) {
        if (this.atOp('}')) break;
        if (this.eatOp('**')) {
          keys.push(null);
          values.push(this.parseOrTest());
          continue;
        }
        keys.push(this.parseExpression());
        this.expectOp(':');
        values.push(this.parseExpression());
      }
      this.expectOp('}');
      return { type: 'Dict', keys, values };
    }
    if (this.atName('for')) {
      const clauses = this.parseComprehension();
      this.expectOp('}');
      return { type: 'SetComp', element: first, clauses };
    }
    const elements = [first];
    while (this.eatOp(',')) {
      if (this.atOp('}')) break;
      elements.push(this.parseStarOrExpression());
    }
    this.expectOp('}');
    return { type: 'Set', elements };
  }

  parseStarOrExpression() {
    if (this.eatOp('*')) return { type: 'Starred', value: this.parseExpression() };
    return this.parseExpression();
  }
}

// Splits an f-string body into literal text and replacement fields.
export function parseFString(body, isRaw) {
  const pieces = [];
  let text = '';
  let i = 0;
  while (i < body.length) {
    const ch = body[i];
    if (ch === '{' && body[i + 1] === '{') { text += '{'; i += 2; continue; }
    if (ch === '}' && body[i + 1] === '}') { text += '}'; i += 2; continue; }
    if (ch !== '{') { text += ch; i++; continue; }

    if (text) { pieces.push({ kind: 'text', text }); text = ''; }
    let depth = 0;
    let j = i + 1;
    let quote = null;
    let expression = '';
    let conversion = null;
    let spec = null;
    while (j < body.length) {
      const inner = body[j];
      if (quote) {
        if (inner === quote) quote = null;
        expression += inner;
        j++;
        continue;
      }
      if (inner === "'" || inner === '"') { quote = inner; expression += inner; j++; continue; }
      if (inner === '(' || inner === '[' || inner === '{') depth++;
      if (inner === ')' || inner === ']') depth--;
      if (inner === '}' && depth === 0) break;
      if (inner === '}') depth--;
      if (inner === '!' && depth === 0 && body[j + 1] !== '=' && body[j - 1] !== '='
          && body[j - 1] !== '<' && body[j - 1] !== '>') {
        conversion = body[j + 1];
        j += 2;
        continue;
      }
      if (inner === ':' && depth === 0) {
        j++;
        spec = '';
        while (j < body.length && body[j] !== '}') { spec += body[j]; j++; }
        break;
      }
      expression += inner;
      j++;
    }
    if (body[j] !== '}') throw syntaxError("f-string: expecting '}'");
    const source = isRaw ? expression : expression;
    pieces.push({
      kind: 'field',
      node: new Parser(source).parseProgram(),
      conversion,
      spec,
    });
    i = j + 1;
  }
  if (text) pieces.push({ kind: 'text', text });
  return pieces;
}

export function parse(source) {
  return new Parser(source).parseProgram();
}

