// Python operator semantics: arithmetic, bitwise, sequence and comparison.

import { typeError, zeroDivisionError, valueError } from './errors.mjs';
import {
  PyList, PyTuple, PyDict, PySet, PyFrozenSet, PyBytes, PyComplex, PyRange,
  PyIterator, isInt, isFloat, isBool, isNumber, typeName, hashKey, iterate,
  strLength, chars,
} from './values.mjs';
import { pyEquals, pyCompare, pyStr, pyRepr } from './compare.mjs';
import { floatRepr } from './floatrepr.mjs';

const asInt = (v) => (isBool(v) ? (v ? 1n : 0n) : v);
const asFloat = (v) => (isBool(v) ? (v ? 1 : 0) : Number(v));

const bothInt = (a, b) => (isInt(a) || isBool(a)) && (isInt(b) || isBool(b));

function bigFloorDiv(a, b) {
  if (b === 0n) throw zeroDivisionError('integer division or modulo by zero');
  let quotient = a / b;
  if (a % b !== 0n && (a < 0n) !== (b < 0n)) quotient -= 1n;
  return quotient;
}

function bigMod(a, b) {
  if (b === 0n) throw zeroDivisionError('integer modulo by zero');
  const rest = a % b;
  if (rest !== 0n && (rest < 0n) !== (b < 0n)) return rest + b;
  return rest;
}

function floatMod(a, b) {
  if (b === 0) throw zeroDivisionError('float modulo');
  const rest = a % b;
  if (rest !== 0 && (rest < 0) !== (b < 0)) return rest + b;
  return rest;
}

function unsupported(op, a, b) {
  return typeError(
    "unsupported operand type(s) for " + op + ": '" + typeName(a) + "' and '" + typeName(b) + "'",
  );
}

function repeatSequence(items, count) {
  const times = Number(asInt(count));
  const out = [];
  for (let i = 0; i < times; i++) for (const item of items) out.push(item);
  return out;
}

export function binaryOp(op, a, b) {
  switch (op) {
    case '+': return add(a, b);
    case '-': return subtract(a, b);
    case '*': return multiply(a, b);
    case '/': return trueDivide(a, b);
    case '//': return floorDivide(a, b);
    case '%': return modulo(a, b);
    case '**': return power(a, b);
    case '&': case '|': case '^': case '<<': case '>>': return bitwise(op, a, b);
    default: throw typeError('unsupported operator ' + op);
  }
}

function add(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInt(a, b)) return asInt(a) + asInt(b);
    return asFloat(a) + asFloat(b);
  }
  if (a instanceof PyComplex || b instanceof PyComplex) {
    const x = toComplex(a);
    const y = toComplex(b);
    return new PyComplex(x.re + y.re, x.im + y.im);
  }
  if (typeof a === 'string' && typeof b === 'string') return a + b;
  if (a instanceof PyList && b instanceof PyList) return new PyList(a.items.concat(b.items));
  if (a instanceof PyTuple && b instanceof PyTuple) return new PyTuple(a.items.concat(b.items));
  if (a instanceof PyBytes && b instanceof PyBytes) {
    const merged = new Uint8Array(a.data.length + b.data.length);
    merged.set(a.data, 0);
    merged.set(b.data, a.data.length);
    return new PyBytes(merged);
  }
  throw unsupported('+', a, b);
}

function subtract(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInt(a, b)) return asInt(a) - asInt(b);
    return asFloat(a) - asFloat(b);
  }
  if (a instanceof PyComplex || b instanceof PyComplex) {
    const x = toComplex(a);
    const y = toComplex(b);
    return new PyComplex(x.re - y.re, x.im - y.im);
  }
  const aSet = a instanceof PySet || a instanceof PyFrozenSet;
  const bSet = b instanceof PySet || b instanceof PyFrozenSet;
  if (aSet && bSet) {
    const out = a instanceof PyFrozenSet ? new PyFrozenSet() : new PySet();
    for (const element of a.elements()) if (!b.has(element)) out.add(element);
    return out;
  }
  throw unsupported('-', a, b);
}

function multiply(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInt(a, b)) return asInt(a) * asInt(b);
    return asFloat(a) * asFloat(b);
  }
  if (a instanceof PyComplex || b instanceof PyComplex) {
    const x = toComplex(a);
    const y = toComplex(b);
    return new PyComplex(x.re * y.re - x.im * y.im, x.re * y.im + x.im * y.re);
  }
  if (typeof a === 'string' && (isInt(b) || isBool(b))) return repeatString(a, b);
  if (typeof b === 'string' && (isInt(a) || isBool(a))) return repeatString(b, a);
  if (a instanceof PyList && (isInt(b) || isBool(b))) return new PyList(repeatSequence(a.items, b));
  if (b instanceof PyList && (isInt(a) || isBool(a))) return new PyList(repeatSequence(b.items, a));
  if (a instanceof PyTuple && (isInt(b) || isBool(b))) return new PyTuple(repeatSequence(a.items, b));
  if (b instanceof PyTuple && (isInt(a) || isBool(a))) return new PyTuple(repeatSequence(b.items, a));
  if (a instanceof PyBytes && (isInt(b) || isBool(b))) {
    return new PyBytes(Uint8Array.from(repeatSequence(Array.from(a.data), b)));
  }
  throw unsupported('*', a, b);
}

function repeatString(text, count) {
  const times = Number(asInt(count));
  return times > 0 ? text.repeat(times) : '';
}

function trueDivide(a, b) {
  if (isNumber(a) && isNumber(b)) {
    const divisor = asFloat(b);
    if (divisor === 0) throw zeroDivisionError('division by zero');
    if (bothInt(a, b)) return divideExact(asInt(a), asInt(b));
    return asFloat(a) / divisor;
  }
  if (a instanceof PyComplex || b instanceof PyComplex) {
    const x = toComplex(a);
    const y = toComplex(b);
    const norm = y.re * y.re + y.im * y.im;
    if (norm === 0) throw zeroDivisionError('complex division by zero');
    return new PyComplex((x.re * y.re + x.im * y.im) / norm, (x.im * y.re - x.re * y.im) / norm);
  }
  throw unsupported('/', a, b);
}

// int/int keeps full precision for values beyond 2**53 by scaling first.
function divideExact(a, b) {
  const quick = Number(a) / Number(b);
  if (Number.isFinite(quick) && Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
    return quick;
  }
  const negative = (a < 0n) !== (b < 0n);
  let x = a < 0n ? -a : a;
  const y = b < 0n ? -b : b;
  let scale = 0;
  while (x / y === 0n) { x *= 10n; scale++; }
  const digits = 20;
  let scaled = x;
  for (let i = 0; i < digits; i++) scaled *= 10n;
  const ratio = Number(scaled / y) / Math.pow(10, digits + scale);
  return negative ? -ratio : ratio;
}

function floorDivide(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInt(a, b)) return bigFloorDiv(asInt(a), asInt(b));
    if (asFloat(b) === 0) throw zeroDivisionError('float floor division by zero');
    return Math.floor(asFloat(a) / asFloat(b));
  }
  throw unsupported('//', a, b);
}

function modulo(a, b) {
  if (typeof a === 'string') return formatPercent(a, b);
  if (isNumber(a) && isNumber(b)) {
    if (bothInt(a, b)) return bigMod(asInt(a), asInt(b));
    return floatMod(asFloat(a), asFloat(b));
  }
  throw unsupported('%', a, b);
}

function power(a, b) {
  if (isNumber(a) && isNumber(b)) {
    if (bothInt(a, b)) {
      const exponent = asInt(b);
      const base = asInt(a);
      if (exponent >= 0n) return base ** exponent;
      if (base === 0n) throw zeroDivisionError('0.0 cannot be raised to a negative power');
      return Math.pow(Number(base), Number(exponent));
    }
    return Math.pow(asFloat(a), asFloat(b));
  }
  throw unsupported('**', a, b);
}

function bitwise(op, a, b) {
  const aSet = a instanceof PySet || a instanceof PyFrozenSet;
  const bSet = b instanceof PySet || b instanceof PyFrozenSet;
  if (aSet && bSet) return setOperation(op, a, b);
  if (isBool(a) && isBool(b) && (op === '&' || op === '|' || op === '^')) {
    if (op === '&') return a && b;
    if (op === '|') return a || b;
    return a !== b;
  }
  if (!bothInt(a, b)) throw unsupported(op, a, b);
  const x = asInt(a);
  const y = asInt(b);
  switch (op) {
    case '&': return x & y;
    case '|': return x | y;
    case '^': return x ^ y;
    case '<<':
      if (y < 0n) throw valueError('negative shift count');
      return x << y;
    default:
      if (y < 0n) throw valueError('negative shift count');
      return x >> y;
  }
}

function setOperation(op, a, b) {
  const out = a instanceof PyFrozenSet ? new PyFrozenSet() : new PySet();
  if (op === '|') {
    for (const element of a.elements()) out.add(element);
    for (const element of b.elements()) out.add(element);
  } else if (op === '&') {
    for (const element of a.elements()) if (b.has(element)) out.add(element);
  } else if (op === '^') {
    for (const element of a.elements()) if (!b.has(element)) out.add(element);
    for (const element of b.elements()) if (!a.has(element)) out.add(element);
  } else {
    throw unsupported(op, a, b);
  }
  return out;
}

export function toComplex(value) {
  if (value instanceof PyComplex) return value;
  if (isNumber(value)) return new PyComplex(asFloat(value), 0);
