  let i = index;
  if (i < 0) i += length;
  if (i < low) i = low;
  if (i > high) i = high;
  return i;
}

// The concrete indices a slice selects, in order.
export function sliceRange(length, lower, upper, stepValue) {
  const step = stepValue === null || stepValue === undefined ? 1 : Number(stepValue);
  if (step === 0) throw valueError('slice step cannot be zero');
