  let stop;
  if (step > 0) {
    start = lower === null || lower === undefined ? 0 : clamp(Number(lower), length, 0, length);
    stop = upper === null || upper === undefined ? length : clamp(Number(upper), length, 0, length);
  } else {
    start = lower === null || lower === undefined
      ? length - 1
      : clamp(Number(lower), length, -1, length - 1);
    stop = upper === null || upper === undefined
      ? -1
      : clamp(Number(upper), length, -1, length - 1);
  }
  const indices = [];
  if (step > 0) for (let i = start; i < stop; i += step) indices.push(i);
  else for (let i = start; i > stop; i += step) indices.push(i);
