  if (args.length < min || (max !== undefined && args.length > max)) {
    throw typeError(name + '() takes ' + min + ' arguments (' + args.length + ' given)');
  }
}

// ---------------------------------------------------------------- conversions

export function toStr(value) { return pyStr(value); }

export function toInt(value, base) {
  if (typeof value === 'string') {
    const radix = base === undefined ? 10 : Number(asInt(base));
    const text = value.trim();
    const parsed = parseIntegerText(text, radix);
    if (parsed === null) {
      throw valueError("invalid literal for int() with base " + radix + ": " + pyRepr(value));
    }
    return parsed;
  }
  if (value instanceof PyBytes) return toInt(new TextDecoder().decode(value.data), base);
  if (isBool(value)) return value ? 1n : 0n;
  if (isInt(value)) return value;
  if (isFloat(value)) {
    if (!Number.isFinite(value)) {
      throw valueError('cannot convert float infinity or NaN to integer');
    }
    return BigInt(Math.trunc(value));
  }
  throw typeError("int() argument must be a string or a number, not '" + typeName(value) + "'");
}

function parseIntegerText(text, radix) {
  let body = text;
  let sign = 1n;
  if (body[0] === '+' || body[0] === '-') {
    if (body[0] === '-') sign = -1n;
    body = body.slice(1);
  }
  let base = radix;
  const lowered = body.toLowerCase();
  if (base === 16 && lowered.startsWith('0x')) body = body.slice(2);
  else if (base === 8 && lowered.startsWith('0o')) body = body.slice(2);
  else if (base === 2 && lowered.startsWith('0b')) body = body.slice(2);
  else if (base === 0) {
    if (lowered.startsWith('0x')) { base = 16; body = body.slice(2); }
    else if (lowered.startsWith('0o')) { base = 8; body = body.slice(2); }
    else if (lowered.startsWith('0b')) { base = 2; body = body.slice(2); }
    else base = 10;
  }
  body = body.split('_').join('');
  if (!body) return null;
  let total = 0n;
  const bigBase = BigInt(base);
  for (const ch of body) {
    const digit = digitValue(ch);
    if (digit === null || digit >= base) return null;
    total = total * bigBase + BigInt(digit);
  }
  return sign * total;
}

function digitValue(ch) {
  if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
  if (ch >= 'a' && ch <= 'z') return ch.charCodeAt(0) - 87;
  if (ch >= 'A' && ch <= 'Z') return ch.charCodeAt(0) - 55;
  return null;
}

export function toFloat(value) {
  if (typeof value === 'string') {
    const text = value.trim().split('_').join('');
    const lowered = text.toLowerCase();
    if (lowered === 'inf' || lowered === 'infinity' || lowered === '+inf' || lowered === '+infinity') {
      return Infinity;
    }
    if (lowered === '-inf' || lowered === '-infinity') return -Infinity;
    if (lowered === 'nan' || lowered === '+nan' || lowered === '-nan') return NaN;
    if (!isNumericText(text)) {
      throw valueError('could not convert string to float: ' + pyRepr(value));
    }
    return Number(text);
  }
  if (isBool(value)) return value ? 1 : 0;
  if (isInt(value)) return Number(value);
  if (isFloat(value)) return value;
  throw typeError("float() argument must be a string or a real number, not '" + typeName(value) + "'");
}

function isNumericText(text) {
  let index = 0;
  if (text[index] === '+' || text[index] === '-') index++;
  let digits = 0;
  while (text[index] >= '0' && text[index] <= '9') { index++; digits++; }
  if (text[index] === '.') {
    index++;
    while (text[index] >= '0' && text[index] <= '9') { index++; digits++; }
  }
  if (digits === 0) return false;
  if (text[index] === 'e' || text[index] === 'E') {
    index++;
    if (text[index] === '+' || text[index] === '-') index++;
    let exponentDigits = 0;
    while (text[index] >= '0' && text[index] <= '9') { index++; exponentDigits++; }
    if (exponentDigits === 0) return false;
  }
  return index === text.length;
}

function toList(value) { return new PyList(iterate(value)); }

function toDict(args, kwargs) {
  const dict = new PyDict();
  if (args.length > 0 && args[0] !== undefined) {
    const source = args[0];
    if (source instanceof PyDict) {
      for (const [key, value] of source.entries()) dict.set(key, value);
    } else {
      for (const pair of iterate(source)) {
        const parts = iterate(pair);
        if (parts.length !== 2) {
          throw valueError('dictionary update sequence element has length ' + parts.length + '; 2 is required');
        }
        dict.set(parts[0], parts[1]);
      }
    }
  }
  if (kwargs) for (const [key, value] of kwargs) dict.set(key, value);
  return dict;
}

function toSet(args, frozen) {
  const set = frozen ? new PyFrozenSet() : new PySet();
  if (args.length > 0 && args[0] !== undefined) for (const item of iterate(args[0])) set.add(item);
  return set;
}

// ------------------------------------------------------------------ numerics

function pyRound(value, digits) {
  if (isInt(value) || isBool(value)) {
    const number = asInt(value);
    return digits === undefined ? number : number;
  }
  const number = asFloat(value);
  if (digits === undefined || digits === null) {
    const floor = Math.floor(number);
    const rest = number - floor;
    let result;
    if (rest > 0.5) result = floor + 1;
    else if (rest < 0.5) result = floor;
    else result = floor % 2 === 0 ? floor : floor + 1; // banker's rounding
    return BigInt(result);
  }
  const places = Number(asInt(digits));
  if (!Number.isFinite(number)) return number;
  if (places <= 0) {
    const scale = Math.pow(10, -places);
    const scaled = number / scale;
    const floor = Math.floor(scaled);
    const rest = scaled - floor;
    let rounded;
    if (rest > 0.5) rounded = floor + 1;
    else if (rest < 0.5) rounded = floor;
    else rounded = floor % 2 === 0 ? floor : floor + 1;
    return rounded * scale;
  }
  return Number(number.toFixed(Math.min(places, 100)));
}

function pyAbs(value) {
  if (isInt(value) || isBool(value)) {
    const number = asInt(value);
    return number < 0n ? -number : number;
  }
  if (isFloat(value)) return Math.abs(value);
  if (value instanceof PyComplex) return Math.sqrt(value.re * value.re + value.im * value.im);
  throw typeError("bad operand type for abs(): '" + typeName(value) + "'");
}

function pySum(items, start) {
  let total = start === undefined ? 0n : start;
  for (const item of items) total = binaryOp('+', total, item);
  return total;
}

function keyedCompare(key, callFunction) {
  if (!key) return (a, b) => pyCompare(a, b);
  return (a, b) => pyCompare(callFunction(key, [a]), callFunction(key, [b]));
}

function pyMinMax(name, args, kwargs, callFunction) {
  const key = kwargs && kwargs.has('key') ? kwargs.get('key') : null;
  const hasDefault = kwargs && kwargs.has('default');
  let items;
  if (args.length === 1) items = iterate(args[0]);
  else items = args;
  if (items.length === 0) {
    if (hasDefault) return kwargs.get('default');
    throw valueError(name + '() arg is an empty sequence');
  }
  const compare = keyedCompare(key, callFunction);
  let best = items[0];
  for (let i = 1; i < items.length; i++) {
    const order = compare(items[i], best);
    if (name === 'max' ? order > 0 : order < 0) best = items[i];
  }
  return best;
}

function pySorted(args, kwargs, callFunction) {
  const items = iterate(args[0]);
  const key = kwargs && kwargs.has('key') ? kwargs.get('key') : null;
  const reverse = kwargs && kwargs.has('reverse') ? isTruthy(kwargs.get('reverse')) : false;
  const compare = keyedCompare(key, callFunction);
  const sorted = stableSort(items, compare);
  if (reverse) sorted.reverse();
  return new PyList(sorted);
}

// Merge sort: stable, and it only ever uses the supplied comparison.
export function stableSort(items, compare) {
  if (items.length < 2) return items.slice();
  const middle = items.length >> 1;
  const left = stableSort(items.slice(0, middle), compare);
  const right = stableSort(items.slice(middle), compare);
  const out = [];
  let i = 0;
  let j = 0;
  while (i < left.length && j < right.length) {
    if (compare(right[j], left[i]) < 0) out.push(right[j++]);
    else out.push(left[i++]);
  }
  while (i < left.length) out.push(left[i++]);
  while (j < right.length) out.push(right[j++]);
  return out;
}

// -------------------------------------------------------------- str methods

function splitWhitespace(text, limit) {
  const parts = [];
  let index = 0;
  let count = 0;
  while (index < text.length) {
    while (index < text.length && WHITESPACE.indexOf(text[index]) >= 0) index++;
    if (index >= text.length) break;
    if (limit >= 0 && count === limit) {
      parts.push(text.slice(index));
      return parts;
    }
    let end = index;
    while (end < text.length && WHITESPACE.indexOf(text[end]) < 0) end++;
    parts.push(text.slice(index, end));
    count++;
    index = end;
  }
  return parts;
}

function splitBy(text, separator, limit) {
  if (separator === '') throw valueError('empty separator');
  const parts = [];
  let index = 0;
  while (limit < 0 || parts.length < limit) {
    const found = text.indexOf(separator, index);
    if (found < 0) break;
    parts.push(text.slice(index, found));
    index = found + separator.length;
  }
  parts.push(text.slice(index));
  return parts;
}

function stripText(text, cutset, left, right) {
  const drop = cutset === undefined || cutset === null ? WHITESPACE : cutset;
  let start = 0;
  let end = text.length;
  if (left) while (start < end && drop.indexOf(text[start]) >= 0) start++;
  if (right) while (end > start && drop.indexOf(text[end - 1]) >= 0) end--;
  return text.slice(start, end);
}

function titleCase(text) {
  let out = '';
  let inWord = false;
  for (const ch of text) {
    const isLetter = ch.toLowerCase() !== ch.toUpperCase();
    if (isLetter) {
      out += inWord ? ch.toLowerCase() : ch.toUpperCase();
      inWord = true;
    } else {
      out += ch;
      inWord = false;
    }
  }
  return out;
}

function strFormat(template, args, kwargs) {
  let out = '';
  let index = 0;
  let auto = 0;
  while (index < template.length) {
    const ch = template[index];
    if (ch === '{' && template[index + 1] === '{') { out += '{'; index += 2; continue; }
    if (ch === '}' && template[index + 1] === '}') { out += '}'; index += 2; continue; }
    if (ch !== '{') { out += ch; index++; continue; }
    let depth = 0;
    let end = index + 1;
    while (end < template.length) {
      if (template[end] === '{') depth++;
      else if (template[end] === '}') {
        if (depth === 0) break;
        depth--;
      }
      end++;
    }
    const field = template.slice(index + 1, end);
    index = end + 1;
    let name = field;
    let spec = '';
    let conversion = null;
    const colon = field.indexOf(':');
    if (colon >= 0) {
      name = field.slice(0, colon);
      spec = field.slice(colon + 1);
    }
    const bang = name.indexOf('!');
    if (bang >= 0) {
      conversion = name[bang + 1];
      name = name.slice(0, bang);
    }
    let value;
    if (name === '') value = args[auto++];
    else if (name[0] >= '0' && name[0] <= '9') value = args[Number(name.split('.')[0])];
    else if (kwargs && kwargs.has(name)) value = kwargs.get(name);
    else throw keyError("'" + name + "'");
    if (value === undefined) throw indexError('Replacement index out of range');
    if (conversion === 'r') value = pyRepr(value);
    else if (conversion === 's') value = pyStr(value);
    out += formatValue(value, spec);
  }
  return out;
}

const STRING_METHODS = {
  upper: (text) => text.toUpperCase(),
  lower: (text) => text.toLowerCase(),
  title: (text) => titleCase(text),
  capitalize: (text) => (text ? text[0].toUpperCase() + text.slice(1).toLowerCase() : text),
  swapcase: (text) => chars(text).map((ch) => (ch === ch.toUpperCase() ? ch.toLowerCase() : ch.toUpperCase())).join(''),
  strip: (text, args) => stripText(text, argAt(args, 0), true, true),
  lstrip: (text, args) => stripText(text, argAt(args, 0), true, false),
  rstrip: (text, args) => stripText(text, argAt(args, 0), false, true),
  split: (text, args) => {
    const separator = argAt(args, 0, null);
    const limit = args.length > 1 ? Number(asInt(args[1])) : -1;
    if (separator === null) return new PyList(splitWhitespace(text, limit));
    return new PyList(splitBy(text, separator, limit));
  },
  rsplit: (text, args) => {
    const separator = argAt(args, 0, null);
    const limit = args.length > 1 ? Number(asInt(args[1])) : -1;
    if (separator === null) {
      const parts = splitWhitespace(text, -1);
      if (limit < 0 || parts.length <= limit) return new PyList(parts);
      const head = parts.slice(0, parts.length - limit).join(' ');
      return new PyList([head].concat(parts.slice(parts.length - limit)));
    }
    const parts = splitBy(text, separator, -1);
    if (limit < 0 || parts.length <= limit) return new PyList(parts);
    const head = parts.slice(0, parts.length - limit).join(separator);
    return new PyList([head].concat(parts.slice(parts.length - limit)));
  },
  splitlines: (text) => {
    const lines = [];
    let current = '';
    for (let i = 0; i < text.length; i++) {
      const ch = text[i];
      if (ch === '\n' || ch === '\r') {
        lines.push(current);
        current = '';
        if (ch === '\r' && text[i + 1] === '\n') i++;
      } else current += ch;
    }
    if (current) lines.push(current);
    return new PyList(lines);
  },
  join: (text, args) => iterate(args[0]).map((item) => {
    if (typeof item !== 'string') {
      throw typeError('sequence item: expected str instance, ' + typeName(item) + ' found');
    }
    return item;
  }).join(text),
  replace: (text, args) => {
    const limit = args.length > 2 ? Number(asInt(args[2])) : -1;
    if (limit < 0) return text.split(args[0]).join(args[1]);
    let out = text;
    let done = 0;
    let index = 0;
    while (done < limit) {
      const found = out.indexOf(args[0], index);
      if (found < 0) break;
      out = out.slice(0, found) + args[1] + out.slice(found + args[0].length);
      index = found + args[1].length;
      done++;
    }
    return out;
  },
  startswith: (text, args) => {
    const prefix = args[0];
    if (prefix instanceof PyTuple) return prefix.items.some((item) => text.startsWith(item));
    return text.startsWith(prefix);
  },
  endswith: (text, args) => {
    const suffix = args[0];
    if (suffix instanceof PyTuple) return suffix.items.some((item) => text.endsWith(item));
    return text.endsWith(suffix);
  },
  find: (text, args) => BigInt(text.indexOf(args[0])),
  rfind: (text, args) => BigInt(text.lastIndexOf(args[0])),
  index: (text, args) => {
    const at = text.indexOf(args[0]);
    if (at < 0) throw valueError('substring not found');
    return BigInt(at);
  },
  count: (text, args) => {
    const needle = args[0];
    if (needle === '') return BigInt(strLength(text) + 1);
    let total = 0;
    let index = 0;
    for (;;) {
      const found = text.indexOf(needle, index);
      if (found < 0) break;
      total++;
      index = found + needle.length;
    }
    return BigInt(total);
  },
  zfill: (text, args) => {
    const width = Number(asInt(args[0]));
    if (text.length >= width) return text;
    const sign = text[0] === '-' || text[0] === '+' ? text[0] : '';
    const body = sign ? text.slice(1) : text;
    return sign + '0'.repeat(width - text.length) + body;
  },
  ljust: (text, args) => {
    const width = Number(asInt(args[0]));
    const fill = argAt(args, 1, ' ');
    return text.length >= width ? text : text + fill.repeat(width - text.length);
  },
  rjust: (text, args) => {
    const width = Number(asInt(args[0]));
    const fill = argAt(args, 1, ' ');
    return text.length >= width ? text : fill.repeat(width - text.length) + text;
  },
  center: (text, args) => {
    const width = Number(asInt(args[0]));
    const fill = argAt(args, 1, ' ');
    if (text.length >= width) return text;
    const missing = width - text.length;
    const left = Math.floor(missing / 2);
    return fill.repeat(left) + text + fill.repeat(missing - left);
  },
  format: (text, args, kwargs) => strFormat(text, args, kwargs),
  encode: (text) => new PyBytes(new TextEncoder().encode(text)),
  isdigit: (text) => text.length > 0 && chars(text).every((ch) => ch >= '0' && ch <= '9'),
  isalpha: (text) => text.length > 0 && chars(text).every((ch) => ch.toLowerCase() !== ch.toUpperCase()),
  isalnum: (text) => text.length > 0 && chars(text).every(
    (ch) => (ch >= '0' && ch <= '9') || ch.toLowerCase() !== ch.toUpperCase(),
  ),
  isspace: (text) => text.length > 0 && chars(text).every((ch) => WHITESPACE.indexOf(ch) >= 0),
  isupper: (text) => text !== text.toLowerCase() && text === text.toUpperCase(),
  islower: (text) => text !== text.toUpperCase() && text === text.toLowerCase(),
  partition: (text, args) => {
    const at = text.indexOf(args[0]);
    if (at < 0) return new PyTuple([text, '', '']);
    return new PyTuple([text.slice(0, at), args[0], text.slice(at + args[0].length)]);
  },
  removeprefix: (text, args) => (text.startsWith(args[0]) ? text.slice(args[0].length) : text),
  removesuffix: (text, args) => (text.endsWith(args[0]) ? text.slice(0, text.length - args[0].length) : text),
};

// ------------------------------------------------------ container methods

const LIST_METHODS = {
  append: (list, args) => { list.items.push(args[0]); return null; },
  extend: (list, args) => { for (const item of iterate(args[0])) list.items.push(item); return null; },
  insert: (list, args) => {
    let at = Number(asInt(args[0]));
    if (at < 0) at = Math.max(0, list.items.length + at);
    list.items.splice(Math.min(at, list.items.length), 0, args[1]);
    return null;
  },
  remove: (list, args) => {
    for (let i = 0; i < list.items.length; i++) {
      if (pyEquals(list.items[i], args[0])) {
        list.items.splice(i, 1);
        return null;
      }
    }
    throw valueError('list.remove(x): x not in list');
  },
  pop: (list, args) => {
    if (list.items.length === 0) throw indexError('pop from empty list');
    let at = args.length > 0 ? Number(asInt(args[0])) : list.items.length - 1;
    if (at < 0) at += list.items.length;
    if (at < 0 || at >= list.items.length) throw indexError('pop index out of range');
    return list.items.splice(at, 1)[0];
  },
  index: (list, args) => {
    for (let i = 0; i < list.items.length; i++) if (pyEquals(list.items[i], args[0])) return BigInt(i);
    throw valueError(pyRepr(args[0]) + ' is not in list');
  },
  count: (list, args) => BigInt(list.items.filter((item) => pyEquals(item, args[0])).length),
  reverse: (list) => { list.items.reverse(); return null; },
  copy: (list) => new PyList(list.items.slice()),
  clear: (list) => { list.items.length = 0; return null; },
};

const DICT_METHODS = {
  keys: (dict) => new PyIterator(dict.keys()),
  values: (dict) => new PyIterator(dict.values()),
  items: (dict) => new PyIterator(dict.entries().map(([key, value]) => new PyTuple([key, value]))),
  get: (dict, args) => {
    const found = dict.get(args[0]);
    return found === undefined ? argAt(args, 1, null) : found;
  },
  pop: (dict, args) => {
    const found = dict.get(args[0]);
    if (found === undefined) {
      if (args.length > 1) return args[1];
      throw keyError(pyRepr(args[0]));
    }
    dict.delete(args[0]);
    return found;
  },
  setdefault: (dict, args) => {
    const found = dict.get(args[0]);
    if (found !== undefined) return found;
    const fallback = argAt(args, 1, null);
    dict.set(args[0], fallback);
    return fallback;
  },
  update: (dict, args, kwargs) => {
    if (args.length > 0) {
      const source = args[0];
      if (source instanceof PyDict) for (const [key, value] of source.entries()) dict.set(key, value);
      else for (const pair of iterate(source)) {
        const parts = iterate(pair);
        dict.set(parts[0], parts[1]);
      }
    }
    if (kwargs) for (const [key, value] of kwargs) dict.set(key, value);
    return null;
  },
  copy: (dict) => {
    const out = new PyDict();
    for (const [key, value] of dict.entries()) out.set(key, value);
    return out;
  },
  clear: (dict) => { dict.slots.clear(); return null; },
};

const SET_METHODS = {
  add: (set, args) => { set.add(args[0]); return null; },
  discard: (set, args) => { set.delete(args[0]); return null; },
  remove: (set, args) => {
    if (!set.delete(args[0])) throw keyError(pyRepr(args[0]));
    return null;
  },
  union: (set, args) => {
    const out = new PySet();
    for (const element of set.elements()) out.add(element);
    for (const other of args) for (const element of iterate(other)) out.add(element);
    return out;
  },
  intersection: (set, args) => {
    let out = set.elements();
    for (const other of args) {
      const filter = new PySet();
      for (const element of iterate(other)) filter.add(element);
      out = out.filter((element) => filter.has(element));
    }
    const result = new PySet();
    for (const element of out) result.add(element);
    return result;
  },
  difference: (set, args) => {
    const out = new PySet();
    const excluded = new PySet();
    for (const other of args) for (const element of iterate(other)) excluded.add(element);
    for (const element of set.elements()) if (!excluded.has(element)) out.add(element);
    return out;
  },
  symmetric_difference: (set, args) => binaryOp('^', set, toSet([args[0]], false)),
  issubset: (set, args) => {
    const other = toSet([args[0]], false);
    return set.elements().every((element) => other.has(element));
  },
  issuperset: (set, args) => toSet([args[0]], false).elements().every((element) => set.has(element)),
  update: (set, args) => {
    for (const other of args) for (const element of iterate(other)) set.add(element);
    return null;
  },
  copy: (set) => {
    const out = set instanceof PyFrozenSet ? new PyFrozenSet() : new PySet();
    for (const element of set.elements()) out.add(element);
    return out;
  },
  clear: (set) => { set.slots.clear(); return null; },
};

const TUPLE_METHODS = {
  index: (tuple, args) => {
    for (let i = 0; i < tuple.items.length; i++) if (pyEquals(tuple.items[i], args[0])) return BigInt(i);
    throw valueError('tuple.index(x): x not in tuple');
  },
  count: (tuple, args) => BigInt(tuple.items.filter((item) => pyEquals(item, args[0])).length),
