// Evaluates the AST produced by parser.mjs, i.e. Python's eval() restricted to
// expressions over builtins.

import { PyError, typeError, nameError, valueError } from './errors.mjs';
import {
  PyList, PyTuple, PyDict, PySet, PyComplex, PyIterator, PyBuiltin,
  PyBoundMethod, PyFunction, isTruthy, iterate, typeName, hashKey,
} from './values.mjs';
import { parse } from './parser.mjs';
import { binaryOp, unaryOp, compareOp } from './operators.mjs';
import { getItem, makeSlice } from './sequence.mjs';
import { makeBuiltins, getAttribute } from './builtins.mjs';
import { formatValue } from './format.mjs';
import { pyRepr, pyStr } from './compare.mjs';

class Scope {
  constructor(parent) {
    this.names = new Map();
    this.parent = parent || null;
  }

  lookup(name) {
    let scope = this;
    while (scope) {
      if (scope.names.has(name)) return scope.names.get(name);
      scope = scope.parent;
    }
    return undefined;
  }

  define(name, value) { this.names.set(name, value); }
}

export class Evaluator {
  constructor(writeOut) {
    this.builtins = makeBuiltins((callee, args, kwargs) => this.call(callee, args, kwargs), writeOut);
    this.globals = new Scope(null);
  }

  evaluateSource(source) {
    return this.evaluate(parse(source), this.globals);
  }

  evaluate(node, scope) {
    switch (node.type) {
      case 'Constant':
        return node.value;
      case 'Imaginary':
        return new PyComplex(0, node.value);
      case 'Ellipsis':
        return null;
      case 'Name': {
        const local = scope.lookup(node.name);
        if (local !== undefined) return local;
        const builtin = this.builtins.get(node.name);
        if (builtin !== undefined) return builtin;
        throw nameError(node.name);
      }
      case 'Tuple':
        return new PyTuple(this.spread(node.elements, scope));
      case 'List':
        return new PyList(this.spread(node.elements, scope));
      case 'Set': {
        const set = new PySet();
        for (const item of this.spread(node.elements, scope)) set.add(item);
        return set;
      }
      case 'Dict': {
        const dict = new PyDict();
        for (let i = 0; i < node.keys.length; i++) {
          if (node.keys[i] === null) {
            const other = this.evaluate(node.values[i], scope);
            if (!(other instanceof PyDict)) throw typeError('argument after ** must be a mapping');
            for (const [key, value] of other.entries()) dict.set(key, value);
            continue;
          }
          const key = this.evaluate(node.keys[i], scope);
          hashKey(key); // reject unhashable keys the way CPython does
          dict.set(key, this.evaluate(node.values[i], scope));
        }
        return dict;
      }
      case 'BinOp':
        return binaryOp(node.op, this.evaluate(node.left, scope), this.evaluate(node.right, scope));
      case 'UnaryOp':
        return unaryOp(node.op, this.evaluate(node.operand, scope));
      case 'BoolOp': {
        const left = this.evaluate(node.left, scope);
        if (node.op === 'and') return isTruthy(left) ? this.evaluate(node.right, scope) : left;
        return isTruthy(left) ? left : this.evaluate(node.right, scope);
      }
      case 'Compare': {
        let left = this.evaluate(node.left, scope);
        for (let i = 0; i < node.ops.length; i++) {
          const right = this.evaluate(node.operands[i], scope);
          if (!compareOp(node.ops[i], left, right)) return false;
          left = right;
        }
        return true;
      }
      case 'IfExp':
        return isTruthy(this.evaluate(node.test, scope))
          ? this.evaluate(node.body, scope)
          : this.evaluate(node.orElse, scope);
      case 'Subscript': {
        const container = this.evaluate(node.value, scope);
        return getItem(container, this.evaluateSlice(node.slice, scope));
      }
      case 'Attribute':
        return getAttribute(this.evaluate(node.value, scope), node.attr);
      case 'Call':
        return this.evaluateCall(node, scope);
      case 'Lambda':
        return new PyFunction(node.params, node.body, scope);
      case 'ListComp':
        return new PyList(this.runComprehension(node, scope));
      case 'SetComp': {
        const set = new PySet();
        for (const item of this.runComprehension(node, scope)) set.add(item);
        return set;
      }
      case 'GeneratorExp':
        return new PyIterator(this.runComprehension(node, scope));
      case 'DictComp': {
        const dict = new PyDict();
        this.iterateClauses(node.clauses, 0, scope, (inner) => {
          dict.set(this.evaluate(node.key, inner), this.evaluate(node.value, inner));
        });
        return dict;
      }
      case 'FormattedString':
        return this.formatString(node, scope);
      case 'Starred':
        throw typeError('can\'t use starred expression here');
      default:
        throw typeError('unsupported expression ' + node.type);
    }
  }

  // Expands *iterable entries inside a display.
  spread(elements, scope) {
    const out = [];
    for (const element of elements) {
      if (element.type === 'Starred') {
        for (const item of iterate(this.evaluate(element.value, scope))) out.push(item);
      } else {
        out.push(this.evaluate(element, scope));
      }
    }
    return out;
  }

  evaluateSlice(node, scope) {
    if (node.type === 'Slice') {
      return makeSlice(
        node.lower === null ? null : Number(this.numeric(node.lower, scope)),
        node.upper === null ? null : Number(this.numeric(node.upper, scope)),
        node.step === null ? null : Number(this.numeric(node.step, scope)),
      );
    }
    return this.evaluate(node, scope);
  }

  numeric(node, scope) {
    const value = this.evaluate(node, scope);
    if (typeof value === 'bigint') return value;
    if (typeof value === 'boolean') return value ? 1n : 0n;
    if (typeof value === 'number' && Number.isInteger(value)) return BigInt(value);
    throw typeError('slice indices must be integers or None');
  }

  evaluateCall(node, scope) {
    const callee = this.evaluate(node.func, scope);
    const args = [];
    for (const argument of node.args) {
      if (argument.type === 'Starred') {
        for (const item of iterate(this.evaluate(argument.value, scope))) args.push(item);
      } else {
        args.push(this.evaluate(argument, scope));
      }
    }
    let kwargs = null;
    for (const keyword of node.keywords) {
      if (kwargs === null) kwargs = new Map();
      if (keyword.name === null) {
        const mapping = this.evaluate(keyword.value, scope);
        if (!(mapping instanceof PyDict)) throw typeError('argument after ** must be a mapping');
        for (const [key, value] of mapping.entries()) kwargs.set(pyStr(key), value);
      } else {
        kwargs.set(keyword.name, this.evaluate(keyword.value, scope));
      }
    }
    return this.call(callee, args, kwargs);
  }

  call(callee, args, kwargs) {
    if (callee instanceof PyBuiltin || callee instanceof PyBoundMethod) {
      return callee.call(args, kwargs || null);
    }
    if (callee instanceof PyFunction) {
      const inner = new Scope(callee.env);
      callee.params.forEach((param, index) => {
        let value;
        if (index < args.length) value = args[index];
        else if (kwargs && kwargs.has(param.name)) value = kwargs.get(param.name);
        else if (param.fallback) value = this.evaluate(param.fallback, callee.env);
        else throw typeError("<lambda>() missing required argument: '" + param.name + "'");
        inner.define(param.name, value);
      });
      return this.evaluate(callee.body, inner);
    }
    throw typeError("'" + typeName(callee) + "' object is not callable");
  }

  runComprehension(node, scope) {
    const out = [];
    this.iterateClauses(node.clauses, 0, scope, (inner) => {
      out.push(this.evaluate(node.element, inner));
    });
    return out;
  }

  // Walks the nested "for ... if ..." clauses, invoking body at the innermost
  // level with a scope holding the loop variables.
  iterateClauses(clauses, index, scope, body) {
    if (index >= clauses.length) {
      body(scope);
      return;
    }
    const clause = clauses[index];
    const iterable = this.evaluate(clause.iterable, scope);
    for (const item of iterate(iterable)) {
      const inner = new Scope(scope);
      this.bindTarget(clause.target, item, inner);
      let keep = true;
      for (const condition of clause.conditions) {
        if (!isTruthy(this.evaluate(condition, inner))) {
          keep = false;
          break;
        }
      }
      if (keep) this.iterateClauses(clauses, index + 1, inner, body);
    }
  }

  bindTarget(target, value, scope) {
    if (target.type === 'NameTarget') {
      scope.define(target.name, value);
      return;
    }
    const items = iterate(value);
    if (items.length !== target.elements.length) {
      throw valueError(
        items.length < target.elements.length
          ? 'not enough values to unpack (expected ' + target.elements.length + ', got ' + items.length + ')'
          : 'too many values to unpack (expected ' + target.elements.length + ')',
      );
    }
    target.elements.forEach((element, index) => this.bindTarget(element, items[index], scope));
  }

  formatString(node, scope) {
    let out = '';
    for (const piece of node.pieces) {
      if (piece.kind === 'text') {
        out += piece.text;
        continue;
      }
      let value = this.evaluate(piece.node, scope);
      if (piece.conversion === 'r') value = pyRepr(value);
      else if (piece.conversion === 's') value = pyStr(value);
      out += formatValue(value, piece.spec || '');
    }
    return out;
  }
}

// Mirrors eval(source) in the reference script.
export function pyEval(source, writeOut) {
  return new Evaluator(writeOut).evaluateSource(source);
}

export { PyError };

