// Representation-graph node types and the tag constants PyYAML uses.

export class ScalarNode {
  constructor(tag, value, style) {
    this.kind = 'scalar';
    this.tag = tag;
    this.value = value;
    this.style = style === undefined ? null : style;
    this.anchor = null;
  }
}

export class SequenceNode {
  constructor(tag, value, flowStyle) {
    this.kind = 'sequence';
    this.tag = tag;
    this.value = value;
    this.flowStyle = flowStyle === undefined ? null : flowStyle;
    this.anchor = null;
  }
}

export class MappingNode {
  constructor(tag, value, flowStyle) {
    this.kind = 'mapping';
    this.tag = tag;
    this.value = value; // array of [keyNode, valueNode]
    this.flowStyle = flowStyle === undefined ? null : flowStyle;
    this.anchor = null;
  }
}

export const TAG = {
  NULL: 'tag:yaml.org,2002:null',
  BOOL: 'tag:yaml.org,2002:bool',
  INT: 'tag:yaml.org,2002:int',
  FLOAT: 'tag:yaml.org,2002:float',
  STR: 'tag:yaml.org,2002:str',
  BINARY: 'tag:yaml.org,2002:binary',
  TIMESTAMP: 'tag:yaml.org,2002:timestamp',
  MERGE: 'tag:yaml.org,2002:merge',
  VALUE: 'tag:yaml.org,2002:value',
  YAML: 'tag:yaml.org,2002:yaml',
  SEQ: 'tag:yaml.org,2002:seq',
  MAP: 'tag:yaml.org,2002:map',
  SET: 'tag:yaml.org,2002:set',
  PYTHON_TUPLE: 'tag:yaml.org,2002:python/tuple',
  PYTHON_COMPLEX: 'tag:yaml.org,2002:python/complex',
  PYTHON_NAME: 'tag:yaml.org,2002:python/name:',
  PYTHON_APPLY: 'tag:yaml.org,2002:python/object/apply:',
};

export const DEFAULT_TAG_PREFIXES = [
  ['!', '!'],
  ['tag:yaml.org,2002:', '!!'],
];

