// Implicit tag resolution for plain scalars.
//
// PyYAML decides whether a scalar may be written unquoted by re-resolving its
// text: if plain resolution yields a different tag than the node carries, the
// scalar has to be quoted.  The upstream rules are regular expressions; they
// are transcribed here as hand written scanners.

import { TAG } from './nodes.mjs';

const BOOL_WORDS = new Set([
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
]);

const NULL_WORDS = new Set(['', '~', 'null', 'Null', 'NULL']);

const isDigit = (ch) => ch !== undefined && ch >= '0' && ch <= '9';
const isHexDigit = (ch) => isDigit(ch)
  || (ch >= 'a' && ch <= 'f')
  || (ch >= 'A' && ch <= 'F');
const isOctalDigit = (ch) => ch !== undefined && ch >= '0' && ch <= '7';
const isBinaryDigit = (ch) => ch === '0' || ch === '1';

// Consumes one or more characters accepted by `accept`, plus "_" separators.
function runOf(text, start, accept) {
  let index = start;
  let seen = 0;
  while (index < text.length) {
    const ch = text[index];
    if (ch === '_') { index++; continue; }
    if (!accept(ch)) break;
    seen++;
    index++;
  }
  return seen > 0 ? index : -1;
}

// Zero or more of `accept` (plus "_"), always succeeds.
function optionalRunOf(text, start, accept) {
  let index = start;
  while (index < text.length) {
    const ch = text[index];
    if (ch === '_' || accept(ch)) index++;
    else break;
  }
  return index;
}

function skipSign(text, index) {
  return text[index] === '-' || text[index] === '+' ? index + 1 : index;
}

// (:[0-5]?[0-9])+ — the sexagesimal tail shared by the int and float rules.
function sexagesimalTail(text, start) {
  let index = start;
  let groups = 0;
  while (text[index] === ':') {
    let next = index + 1;
    if (text[next] >= '0' && text[next] <= '5' && isDigit(text[next + 1])) next += 2;
    else if (isDigit(text[next])) next += 1;
    else return -1;
    index = next;
    groups++;
  }
  return groups > 0 ? index : -1;
}

