  if (text[index] === '0' && text[index + 1] === 'b') {
    return runOf(text, index + 2, isBinaryDigit) === text.length;
  }
  // 0x[0-9a-fA-F_]+
  if (text[index] === '0' && text[index + 1] === 'x') {
    return runOf(text, index + 2, isHexDigit) === text.length;
  }
  // 0[0-7_]+
  if (text[index] === '0' && index + 1 < text.length) {
    if (runOf(text, index + 1, isOctalDigit) === text.length) return true;
  }
