  if (text[index] === '0' && index + 1 === text.length) return true;
  if (!(text[index] >= '1' && text[index] <= '9')) return false;
  const afterDigits = optionalRunOf(text, index + 1, isDigit);
  if (afterDigits === text.length) return true;
  // [1-9][0-9_]*(:[0-5]?[0-9])+
  return sexagesimalTail(text, afterDigits) === text.length;
