  index = digitsBetween(text, index + 1, 1, 2);
  if (index < 0) return false;
  if (text[index] === 'T' || text[index] === 't') {
    index++;
  } else if (text[index] === ' ' || text[index] === '\t') {
    while (text[index] === ' ' || text[index] === '\t') index++;
  } else {
    return false;
  }
  index = digitsBetween(text, index, 1, 2);
  if (index < 0 || text[index] !== ':') return false;
  index = digitsExactly(text, index + 1, 2);
  if (index < 0 || text[index] !== ':') return false;
  index = digitsExactly(text, index + 1, 2);
  if (index < 0) return false;
  if (text[index] === '.') {
    index++;
    while (isDigit(text[index])) index++;
  }
