  if (text[index] === 'Z') return index + 1 === text.length;
  if (text[index] === '-' || text[index] === '+') {
    index = digitsBetween(text, index + 1, 1, 2);
    if (index < 0) return false;
    if (index === text.length) return true;
    if (text[index] !== ':') return false;
    index = digitsExactly(text, index + 1, 2);
    return index === text.length;
  }
  return index === text.length;
}

// Resolvers keyed by first character, in PyYAML's registration order.
const RESOLVERS = new Map();

function register(tag, matches, firstCharacters) {
  for (const first of firstCharacters) {
    if (!RESOLVERS.has(first)) RESOLVERS.set(first, []);
    RESOLVERS.get(first).push({ tag, matches });
  }
}

