register(TAG.FLOAT, matchesFloat, '-+0123456789.');
register(TAG.INT, matchesInt, '-+0123456789');
register(TAG.MERGE, (text) => text === '<<', '<');
register(TAG.NULL, (text) => NULL_WORDS.has(text), ['~', 'n', 'N', '']);
register(TAG.TIMESTAMP, matchesTimestamp, '0123456789');
register(TAG.VALUE, (text) => text === '=', '=');
register(TAG.YAML, (text) => text === '!' || text === '&' || text === '*', '!&*');

