export function resolveScalar(text) {
  const candidates = RESOLVERS.get(text === '' ? '' : text[0]);
  if (candidates) {
    for (const candidate of candidates) {
      if (candidate.matches(text)) return candidate.tag;
    }
  }
  return TAG.STR;
}

