// base64 encoding that matches Python's base64.encodebytes(): 76 characters
// per line, every line terminated by a newline.

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

export function encodeBase64(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const remaining = bytes.length - i;
    const first = bytes[i];
    const second = remaining > 1 ? bytes[i + 1] : 0;
    const third = remaining > 2 ? bytes[i + 2] : 0;
    out += ALPHABET[first >> 2];
    out += ALPHABET[((first & 0x03) << 4) | (second >> 4)];
    out += remaining > 1 ? ALPHABET[((second & 0x0f) << 2) | (third >> 6)] : '=';
    out += remaining > 2 ? ALPHABET[third & 0x3f] : '=';
  }
  return out;
}

export function encodeBytesBlock(bytes) {
  const encoded = encodeBase64(bytes);
  let out = '';
  for (let i = 0; i < encoded.length; i += 76) out += encoded.slice(i, i + 76) + '\n';
  return out;
}

