// Turns Python values into a YAML representation graph, mirroring PyYAML's
// Representer (the full Dumper, so tuples/sets/complex get python-specific
// tags).

import { PyError } from '../python/errors.mjs';
import {
  PyList, PyTuple, PyDict, PySet, PyFrozenSet, PyBytes, PyComplex, PyRange,
  PyTypeRef, isInt, isFloat, isBool, typeName,
} from '../python/values.mjs';
import { pyCompare } from '../python/compare.mjs';
import { stableSort } from '../python/builtins.mjs';
import { floatRepr } from '../python/floatrepr.mjs';
import { ScalarNode, SequenceNode, MappingNode, TAG } from './nodes.mjs';
import { encodeBytesBlock } from './base64.mjs';

// PyYAML only shares (anchors) nodes for values it cannot inline; scalars and
// the empty tuple are always duplicated.
function ignoreAliases(data) {
  if (data === null) return true;
  if (typeof data === 'string' || typeof data === 'boolean') return true;
  if (typeof data === 'bigint' || typeof data === 'number') return true;
  if (data instanceof PyBytes) return true;
  if (data instanceof PyTuple && data.items.length === 0) return true;
  return false;
}

// PyYAML's represent_float(): repr(), lowercased, with ".0" spliced in when an
// exponent form would otherwise look like an int.
function floatValueText(value) {
  if (Number.isNaN(value)) return '.nan';
  if (value === Infinity) return '.inf';
  if (value === -Infinity) return '-.inf';
  let text = floatRepr(value).toLowerCase();
  if (text.indexOf('.') < 0 && text.indexOf('e') >= 0) {
    text = text.replace('e', '.0e');
  }
  return text;
}

function complexValueText(value) {
  if (value.im === 0) return floatRepr(value.re);
  if (value.re === 0) return floatRepr(value.im) + 'j';
  if (value.im > 0) return floatRepr(value.re) + '+' + floatRepr(value.im) + 'j';
  return floatRepr(value.re) + floatRepr(value.im) + 'j';
}

export class Representer {
  constructor(options) {
    const settings = options || {};
    this.defaultStyle = settings.defaultStyle === undefined ? null : settings.defaultStyle;
    this.defaultFlowStyle = settings.defaultFlowStyle === undefined ? false : settings.defaultFlowStyle;
    this.sortKeys = settings.sortKeys === undefined ? true : settings.sortKeys;
    this.representedObjects = new Map();
    this.aliasKey = null;
  }

  represent(data) {
    this.representedObjects = new Map();
    this.aliasKey = null;
    return this.representData(data);
  }

  representData(data) {
    this.aliasKey = ignoreAliases(data) ? null : data;
    if (this.aliasKey !== null) {
      const existing = this.representedObjects.get(this.aliasKey);
      if (existing !== undefined) return existing;
    }

    if (data === null) return this.representScalar(TAG.NULL, 'null');
    if (typeof data === 'boolean') return this.representScalar(TAG.BOOL, data ? 'true' : 'false');
    if (isInt(data)) return this.representScalar(TAG.INT, data.toString());
    if (isFloat(data)) return this.representScalar(TAG.FLOAT, floatValueText(data));
    if (typeof data === 'string') return this.representScalar(TAG.STR, data);
    if (data instanceof PyBytes) {
      return this.representScalar(TAG.BINARY, encodeBytesBlock(data.data), '|');
    }
    if (data instanceof PyList) return this.representSequence(TAG.SEQ, data.items);
    if (data instanceof PyTuple) return this.representSequence(TAG.PYTHON_TUPLE, data.items);
    if (data instanceof PyDict) return this.representMapping(TAG.MAP, data.entries());
    if (data instanceof PySet) {
      return this.representMapping(TAG.SET, data.elements().map((element) => [element, null]));
    }
    if (data instanceof PyFrozenSet) {
      // reduce_ex gives (frozenset, ([elements],)) -> apply with one list arg.
      return this.representSequence(
        TAG.PYTHON_APPLY + 'builtins.frozenset',
        [new PyList(data.elements())],
      );
    }
    if (data instanceof PyRange) {
      return this.representSequence(
        TAG.PYTHON_APPLY + 'builtins.range',
        [data.start, data.stop, data.step],
      );
    }
    if (data instanceof PyComplex) {
      return this.representScalar(TAG.PYTHON_COMPLEX, complexValueText(data));
    }
    if (data instanceof PyTypeRef) {
      return this.representScalar(TAG.PYTHON_NAME + 'builtins.' + data.name, '');
    }
    throw new PyError('TypeError', "cannot pickle '" + typeName(data) + "' object");
  }

  representScalar(tag, value, style) {
    const chosen = style === undefined || style === null ? this.defaultStyle : style;
    const node = new ScalarNode(tag, value, chosen);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    return node;
  }

  representSequence(tag, items) {
    const value = [];
    const node = new SequenceNode(tag, value, null);
    const aliasKey = this.aliasKey;
    if (aliasKey !== null) this.representedObjects.set(aliasKey, node);
    for (const item of items) value.push(this.representData(item));
    node.flowStyle = this.defaultFlowStyle;
    return node;
  }

  representMapping(tag, entries) {
    const value = [];
    const node = new MappingNode(tag, value, null);
    const aliasKey = this.aliasKey;
    if (aliasKey !== null) this.representedObjects.set(aliasKey, node);
    let pairs = entries;
    if (this.sortKeys) pairs = sortEntries(pairs);
    for (const [key, item] of pairs) {
      const keyNode = this.representData(key);
      const valueNode = this.representData(item);
      value.push([keyNode, valueNode]);
    }
    node.flowStyle = this.defaultFlowStyle;
    return node;
  }
}

// sorted(mapping.items()) with PyYAML's "except TypeError: pass" fallback.
function sortEntries(entries) {
  try {
    return stableSort(entries, (left, right) => {
      const order = pyCompare(left[0], right[0]);
      if (order !== 0) return order;
      return pyCompare(left[1], right[1]);
    });
  } catch (error) {
    if (error instanceof PyError) return entries;
    throw error;
  }
