// Scalar analysis: decides which scalar styles are legal for a given text.
// Transcribed from PyYAML's Emitter.analyze_scalar, including its quirks.

const WHITESPACE_LIKE = '\0 \t\r\n\x85  ';
const LINE_BREAKS = '\n\x85  ';

const isWhitespaceLike = (ch) => ch !== undefined && WHITESPACE_LIKE.indexOf(ch) >= 0;
const isLineBreak = (ch) => ch !== undefined && LINE_BREAKS.indexOf(ch) >= 0;

export function analyzeScalar(scalar, allowUnicode) {
  if (!scalar) {
    return {
      scalar,
      empty: true,
      multiline: false,
      allowFlowPlain: false,
      allowBlockPlain: true,
      allowSingleQuoted: true,
      allowDoubleQuoted: true,
      allowBlock: false,
    };
  }

  let blockIndicators = false;
  let flowIndicators = false;
  let lineBreaks = false;
  let specialCharacters = false;

  let leadingSpace = false;
  let leadingBreak = false;
  let trailingSpace = false;
  let trailingBreak = false;
  let breakSpace = false;
  let spaceBreak = false;

  if (scalar.startsWith('---') || scalar.startsWith('...')) {
    blockIndicators = true;
    flowIndicators = true;
  }

  let precededByWhitespace = true;
  let followedByWhitespace = scalar.length === 1 || isWhitespaceLike(scalar[1]);
  let previousSpace = false;
  let previousBreak = false;

  let index = 0;
  while (index < scalar.length) {
    const ch = scalar[index];

    if (index === 0) {
      if ('#,[]{}&*!|>\'"%@`'.indexOf(ch) >= 0) {
        flowIndicators = true;
        blockIndicators = true;
      }
      if (ch === '?' || ch === ':') {
        flowIndicators = true;
        if (followedByWhitespace) blockIndicators = true;
      }
      if (ch === '-' && followedByWhitespace) {
        flowIndicators = true;
        blockIndicators = true;
      }
    } else {
      if (',?[]{}'.indexOf(ch) >= 0) flowIndicators = true;
      if (ch === ':') {
        flowIndicators = true;
        if (followedByWhitespace) blockIndicators = true;
      }
      if (ch === '#' && precededByWhitespace) {
        flowIndicators = true;
        blockIndicators = true;
      }
    }

    if (isLineBreak(ch)) lineBreaks = true;
    if (!(ch === '\n' || (ch >= '\x20' && ch <= '\x7E'))) {
      const code = ch.codePointAt(0);
      const printableUnicode = ch === '\x85'
        || (code >= 0xa0 && code <= 0xd7ff)
        || (code >= 0xe000 && code <= 0xfffd)
        || (code >= 0x10000 && code < 0x10ffff);
      if (printableUnicode && ch !== '﻿') {
        if (!allowUnicode) specialCharacters = true;
      } else {
        specialCharacters = true;
      }
    }

    if (ch === ' ') {
      if (index === 0) leadingSpace = true;
      if (index === scalar.length - 1) trailingSpace = true;
      if (previousBreak) breakSpace = true;
      previousSpace = true;
      previousBreak = false;
    } else if (isLineBreak(ch)) {
      if (index === 0) leadingBreak = true;
      if (index === scalar.length - 1) trailingBreak = true;
      if (previousSpace) spaceBreak = true;
      previousSpace = false;
      previousBreak = true;
    } else {
      previousSpace = false;
      previousBreak = false;
    }

    // Upstream advances the cursor before recomputing these two flags, which
    // makes followedByWhitespace peek one character too far; kept as-is so the
    // output matches byte for byte.
    index += 1;
    precededByWhitespace = isWhitespaceLike(ch);
    followedByWhitespace = index + 1 >= scalar.length || isWhitespaceLike(scalar[index + 1]);
  }

  let allowFlowPlain = true;
  let allowBlockPlain = true;
  let allowSingleQuoted = true;
  const allowDoubleQuoted = true;
  let allowBlock = true;

  if (leadingSpace || leadingBreak || trailingSpace || trailingBreak) {
    allowFlowPlain = false;
    allowBlockPlain = false;
  }
  if (trailingSpace) allowBlock = false;
  if (breakSpace) {
    allowFlowPlain = false;
    allowBlockPlain = false;
    allowSingleQuoted = false;
  }
  if (spaceBreak || specialCharacters) {
    allowFlowPlain = false;
    allowBlockPlain = false;
    allowSingleQuoted = false;
    allowBlock = false;
  }
  if (lineBreaks) {
    allowFlowPlain = false;
    allowBlockPlain = false;
  }
  if (flowIndicators) allowFlowPlain = false;
  if (blockIndicators) allowBlockPlain = false;

  return {
    scalar,
    empty: false,
    multiline: lineBreaks,
    allowFlowPlain,
    allowBlockPlain,
    allowSingleQuoted,
    allowDoubleQuoted,
    allowBlock,
  };
}

export { isLineBreak, isWhitespaceLike, LINE_BREAKS };

