// Anchor assignment, mirroring PyYAML's Serializer.
//
// A node that appears more than once in the graph gets an anchor the second
// time it is reached during a depth-first walk; the numbering follows that
// discovery order.

const ANCHOR_PREFIX = 'id';

function anchorName(counter) {
  let digits = String(counter);
  while (digits.length < 3) digits = '0' + digits;
  return ANCHOR_PREFIX + digits;
}

export function assignAnchors(root) {
  const seen = new Map(); // node -> anchor or null
  const state = { last: 0 };
  walk(root, seen, state);
  for (const [node, anchor] of seen) node.anchor = anchor;
  return seen;
}

function walk(node, seen, state) {
  if (seen.has(node)) {
    if (seen.get(node) === null) {
      state.last += 1;
      seen.set(node, anchorName(state.last));
    }
    return;
  }
  seen.set(node, null);
  if (node.kind === 'sequence') {
    for (const item of node.value) walk(item, seen, state);
  } else if (node.kind === 'mapping') {
    for (const [key, value] of node.value) {
      walk(key, seen, state);
      walk(value, seen, state);
    }
  }
}

