// The YAML emitter: a port of PyYAML's Emitter, keeping its column tracking,
// indentation rules, scalar styles and line-folding behaviour.
//
// PyYAML drives the writer from an event stream; because the node graph is
// already available here the same decisions are taken during a recursive walk.
// The state variables (column/whitespace/indention/indent stack/flow level and
// the *_context flags) are updated at exactly the same points.

import { TAG } from './nodes.mjs';
import { analyzeScalar, isLineBreak } from './analysis.mjs';
import { resolveScalar } from './resolver.mjs';

const ESCAPE_REPLACEMENTS = new Map([
  ['\0', '0'],
  ['\x07', 'a'],
  ['\b', 'b'],
  ['\t', 't'],
  ['\n', 'n'],
  ['\v', 'v'],
  ['\f', 'f'],
  ['\r', 'r'],
  ['\x1B', 'e'],
  ['"', '"'],
  ['\\', '\\'],
  ['\x85', 'N'],
  ['\xA0', '_'],
  [' ', 'L'],
  [' ', 'P'],
]);

const DOUBLE_QUOTE_FORCED = '"\\\x85  ﻿';

// Characters that may appear unescaped in a tag suffix.
const TAG_SAFE = "-;/?:@&=+$,_.~*'()[]";

function hexUpper(code, width) {
  let digits = code.toString(16).toUpperCase();
  while (digits.length < width) digits = '0' + digits;
  return digits;
}

// '!!' handle for the standard tag prefix, verbatim form otherwise.
export function prepareTag(tag) {
  if (!tag) throw new Error('tag must not be empty');
  if (tag === '!') return tag;
  let handle = null;
  let suffix = tag;
  // sorted(tag_prefixes) == ['!', 'tag:yaml.org,2002:']; the last match wins.
  for (const [prefix, mapped] of [['!', '!'], ['tag:yaml.org,2002:', '!!']]) {
    if (tag.startsWith(prefix) && (prefix === '!' || prefix.length < tag.length)) {
      handle = mapped;
      suffix = tag.slice(prefix.length);
    }
  }
  let out = '';
  for (const ch of suffix) {
    const isAlphanumeric = (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z');
    if (isAlphanumeric || TAG_SAFE.indexOf(ch) >= 0 || (ch === '!' && handle !== '!')) {
      out += ch;
    } else {
      for (const byte of new TextEncoder().encode(ch)) out += '%' + hexUpper(byte, 2);
    }
  }
  return handle ? handle + out : '!<' + out + '>';
}

export class Emitter {
  constructor(options) {
    const settings = options || {};
    this.chunks = [];
    this.column = 0;
    this.whitespace = true;
    this.indention = true;
    this.openEnded = false;
    this.indent = null;
    this.indents = [];
    this.flowLevel = 0;
    this.rootContext = false;
    this.sequenceContext = false;
    this.mappingContext = false;
    this.simpleKeyContext = false;
    this.canonical = settings.canonical === undefined ? false : settings.canonical;
    this.allowUnicode = settings.allowUnicode === undefined ? false : settings.allowUnicode;
    this.bestIndent = 2;
    if (settings.indent && settings.indent > 1 && settings.indent < 10) this.bestIndent = settings.indent;
    this.bestWidth = 80;
    if (settings.width && settings.width > this.bestIndent * 2) this.bestWidth = settings.width;
    this.analysis = null;
    this.style = null;
    this.preparedTag = null;
    this.preparedAnchor = null;
    this.serialized = new Set();
  }

  // Emits a single implicit document, as yaml.dump() does with its defaults.
  emit(root) {
    this.expectNode(root, { root: true });
    this.writeIndent(); // DocumentEndEvent
    if (this.openEnded) { // StreamEndEvent
      this.writeIndicator('...', true);
      this.writeIndent();
    }
    return this.chunks.join('');
  }

  // ------------------------------------------------------------- raw writing

  write(data) { this.chunks.push(data); }

  writeIndicator(indicator, needWhitespace, whitespace, indention) {
    const data = this.whitespace || !needWhitespace ? indicator : ' ' + indicator;
    this.whitespace = whitespace === true;
    this.indention = this.indention && indention === true;
    this.column += data.length;
    this.openEnded = false;
    this.write(data);
  }

  writeIndent() {
    const indent = this.indent || 0;
    if (!this.indention || this.column > indent
        || (this.column === indent && !this.whitespace)) {
      this.writeLineBreak();
    }
    if (this.column < indent) {
      this.whitespace = true;
      this.write(' '.repeat(indent - this.column));
      this.column = indent;
    }
  }

  writeLineBreak(data) {
    this.whitespace = true;
    this.indention = true;
    this.column = 0;
    this.write(data === undefined ? '\n' : data);
  }

  increaseIndent(flow, indentless) {
    this.indents.push(this.indent);
    if (this.indent === null) this.indent = flow ? this.bestIndent : 0;
    else if (!indentless) this.indent += this.bestIndent;
  }

  // --------------------------------------------------------- node dispatch

  expectNode(node, context) {
    this.rootContext = context.root === true;
    this.sequenceContext = context.sequence === true;
    this.mappingContext = context.mapping === true;
    this.simpleKeyContext = context.simpleKey === true;

    if (this.serialized.has(node)) { // AliasEvent
      this.processAnchor('*', node);
      return;
    }
    this.serialized.add(node);
    this.processAnchor('&', node);
    this.processTag(node);

    if (node.kind === 'scalar') {
      this.expectScalar(node);
    } else if (node.kind === 'sequence') {
      if (this.flowLevel || this.canonical || node.flowStyle || node.value.length === 0) {
        this.expectFlowSequence(node);
      } else {
        this.expectBlockSequence(node);
      }
    } else if (this.flowLevel || this.canonical || node.flowStyle || node.value.length === 0) {
      this.expectFlowMapping(node);
    } else {
      this.expectBlockMapping(node);
    }
  }

  expectScalar(node) {
    this.increaseIndent(true, false);
    this.processScalar(node);
    this.indent = this.indents.pop();
  }

  expectFlowSequence(node) {
    this.writeIndicator('[', true, true);
    this.flowLevel += 1;
    this.increaseIndent(true, false);
    let first = true;
    for (const item of node.value) {
      if (!first) this.writeIndicator(',', false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.expectNode(item, { sequence: true });
      first = false;
    }
    this.indent = this.indents.pop();
    this.flowLevel -= 1;
    this.writeIndicator(']', false);
  }

  expectFlowMapping(node) {
    this.writeIndicator('{', true, true);
    this.flowLevel += 1;
    this.increaseIndent(true, false);
    let first = true;
    for (const [keyNode, valueNode] of node.value) {
      if (!first) this.writeIndicator(',', false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey(keyNode)) {
        this.expectNode(keyNode, { mapping: true, simpleKey: true });
        this.writeIndicator(':', false);
        this.expectNode(valueNode, { mapping: true });
      } else {
        this.writeIndicator('?', true);
        this.expectNode(keyNode, { mapping: true });
        this.writeIndicator(':', true);
        this.expectNode(valueNode, { mapping: true });
      }
      first = false;
    }
    this.indent = this.indents.pop();
    this.flowLevel -= 1;
    this.writeIndicator('}', false);
  }

  expectBlockSequence(node) {
    // A sequence that is the value of a mapping key stays at the parent's
    // indentation level.
    const indentless = this.mappingContext && !this.indention;
    this.increaseIndent(false, indentless);
    for (const item of node.value) {
      this.writeIndent();
      this.writeIndicator('-', true, false, true);
      this.expectNode(item, { sequence: true });
    }
    this.indent = this.indents.pop();
  }

  expectBlockMapping(node) {
    this.increaseIndent(false, false);
    for (const [keyNode, valueNode] of node.value) {
      this.writeIndent();
      if (this.checkSimpleKey(keyNode)) {
        this.expectNode(keyNode, { mapping: true, simpleKey: true });
        this.writeIndicator(':', false);
        this.expectNode(valueNode, { mapping: true });
      } else {
        this.writeIndicator('?', true, false, true);
        this.expectNode(keyNode, { mapping: true });
        this.writeIndent();
        this.writeIndicator(':', true, false, true);
        this.expectNode(valueNode, { mapping: true });
      }
    }
    this.indent = this.indents.pop();
  }

  // ------------------------------------------------------------- decisions

  checkSimpleKey(node) {
    let length = 0;
    const isAlias = this.serialized.has(node);
    if (node.anchor !== null) length += node.anchor.length;
    if (!isAlias && node.tag !== null) {
      if (this.preparedTag === null) this.preparedTag = prepareTag(node.tag);
      length += this.preparedTag.length;
    }
    if (!isAlias && node.kind === 'scalar') {
      if (this.analysis === null) this.analysis = analyzeScalar(node.value, this.allowUnicode);
      length += Array.from(this.analysis.scalar).length;
    }
    if (length >= 128) return false;
    if (isAlias) return true;
    if (node.kind === 'scalar') return !this.analysis.empty && !this.analysis.multiline;
    return node.value.length === 0;
  }

  // implicit[0]: the plain form would resolve back to this tag.
  // implicit[1]: the tag is the default scalar tag (str).
  scalarImplicit(node) {
    return [node.tag === resolveScalar(node.value), node.tag === TAG.STR];
  }

  processAnchor(indicator, node) {
    if (node.anchor === null) {
      this.preparedAnchor = null;
      return;
    }
    if (this.preparedAnchor === null) this.preparedAnchor = node.anchor;
    if (this.preparedAnchor) this.writeIndicator(indicator + this.preparedAnchor, true);
    this.preparedAnchor = null;
  }

  processTag(node) {
    const tag = node.tag;
    if (node.kind === 'scalar') {
      if (this.style === null) this.style = this.chooseScalarStyle(node);
      const implicit = this.scalarImplicit(node);
      if ((this.style === '' && implicit[0]) || (this.style !== '' && implicit[1])) {
        if (!this.canonical) {
          this.preparedTag = null;
          return;
        }
      }
    } else {
      const implicit = node.kind === 'sequence' ? tag === TAG.SEQ : tag === TAG.MAP;
      if (!this.canonical && implicit) {
        this.preparedTag = null;
        return;
      }
    }
    if (this.preparedTag === null) this.preparedTag = prepareTag(tag);
    if (this.preparedTag) this.writeIndicator(this.preparedTag, true);
    this.preparedTag = null;
  }

  chooseScalarStyle(node) {
    if (this.analysis === null) this.analysis = analyzeScalar(node.value, this.allowUnicode);
    if (node.style === '"' || this.canonical) return '"';
    const implicit = this.scalarImplicit(node);
    if (!node.style && implicit[0]) {
      if (!(this.simpleKeyContext && (this.analysis.empty || this.analysis.multiline))
          && ((this.flowLevel && this.analysis.allowFlowPlain)
            || (!this.flowLevel && this.analysis.allowBlockPlain))) {
        return '';
      }
    }
    if (node.style && (node.style === '|' || node.style === '>')) {
      if (!this.flowLevel && !this.simpleKeyContext && this.analysis.allowBlock) return node.style;
    }
    if (!node.style || node.style === "'") {
      if (this.analysis.allowSingleQuoted && !(this.simpleKeyContext && this.analysis.multiline)) {
        return "'";
      }
    }
    return '"';
  }

  processScalar(node) {
    if (this.analysis === null) this.analysis = analyzeScalar(node.value, this.allowUnicode);
    if (this.style === null) this.style = this.chooseScalarStyle(node);
    const split = !this.simpleKeyContext;
    if (this.style === '"') this.writeDoubleQuoted(this.analysis.scalar, split);
    else if (this.style === "'") this.writeSingleQuoted(this.analysis.scalar, split);
    else if (this.style === '|') this.writeLiteral(this.analysis.scalar);
    else this.writePlain(this.analysis.scalar, split);
    this.analysis = null;
    this.style = null;
  }

  // ------------------------------------------------------- scalar writers

  writeSingleQuoted(text, split) {
    this.writeIndicator("'", true);
    const points = Array.from(text);
    let spaces = false;
    let breaks = false;
    let start = 0;
    let end = 0;
    while (end <= points.length) {
      const ch = end < points.length ? points[end] : null;
      if (spaces) {
        if (ch === null || ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split
              && start !== 0 && end !== points.length) {
            this.writeIndent();
          } else {
            this.column += end - start;
            this.write(points.slice(start, end).join(''));
          }
          start = end;
        }
      } else if (breaks) {
        if (ch === null || !isLineBreak(ch)) {
          if (points[start] === '\n') this.writeLineBreak();
          for (const br of points.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          start = end;
        }
      } else if (ch === null || ch === ' ' || isLineBreak(ch) || ch === "'") {
        if (start < end) {
          this.column += end - start;
          this.write(points.slice(start, end).join(''));
          start = end;
        }
      }
      if (ch === "'") {
        this.column += 2;
        this.write("''");
        start = end + 1;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = isLineBreak(ch);
      }
      end += 1;
    }
    this.writeIndicator("'", false);
  }

  writeDoubleQuoted(text, split) {
    this.writeIndicator('"', true);
    const points = Array.from(text);
    let start = 0;
    let end = 0;
    while (end <= points.length) {
      const ch = end < points.length ? points[end] : null;
      if (ch === null || DOUBLE_QUOTE_FORCED.indexOf(ch) >= 0 || !this.isPrintable(ch)) {
        if (start < end) {
          this.column += end - start;
          this.write(points.slice(start, end).join(''));
          start = end;
        }
        if (ch !== null) {
          let data;
          const code = ch.codePointAt(0);
          if (ESCAPE_REPLACEMENTS.has(ch)) data = '\\' + ESCAPE_REPLACEMENTS.get(ch);
          else if (code <= 0xff) data = '\\x' + hexUpper(code, 2);
          else if (code <= 0xffff) data = '\\u' + hexUpper(code, 4);
          else data = '\\U' + hexUpper(code, 8);
          this.column += data.length;
          this.write(data);
          start = end + 1;
        }
      }
      if (end > 0 && end < points.length - 1 && (ch === ' ' || start >= end)
          && this.column + (end - start) > this.bestWidth && split) {
        const data = points.slice(start, end).join('') + '\\';
        if (start < end) start = end;
        this.column += end - start + 1;
        this.write(data);
        this.writeIndent();
        this.whitespace = false;
        this.indention = false;
        if (points[start] === ' ') {
          this.column += 1;
          this.write('\\');
        }
      }
      end += 1;
    }
    this.writeIndicator('"', false);
  }

  isPrintable(ch) {
    if (ch >= '\x20' && ch <= '\x7E') return true;
    if (!this.allowUnicode) return false;
    const code = ch.codePointAt(0);
    return (code >= 0xa0 && code <= 0xd7ff)
      || (code >= 0xe000 && code <= 0xfffd)
      || (code >= 0x10000 && code < 0x10ffff);
  }

  writeLiteral(text) {
    const points = Array.from(text);
    const hints = this.determineBlockHints(points);
    this.writeIndicator('|' + hints, true);
    if (hints.endsWith('+')) this.openEnded = true;
    this.writeLineBreak();
    let breaks = true;
    let start = 0;
    let end = 0;
    while (end <= points.length) {
      const ch = end < points.length ? points[end] : null;
      if (breaks) {
        if (ch === null || !isLineBreak(ch)) {
          for (const br of points.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (ch === null || isLineBreak(ch)) {
        this.write(points.slice(start, end).join(''));
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) breaks = isLineBreak(ch);
      end += 1;
    }
  }

  determineBlockHints(points) {
    let hints = '';
    if (points.length) {
      if (points[0] === ' ' || isLineBreak(points[0])) hints += String(this.bestIndent);
      if (!isLineBreak(points[points.length - 1])) hints += '-';
      else if (points.length === 1 || isLineBreak(points[points.length - 2])) hints += '+';
    }
    return hints;
  }

  writePlain(text, split) {
    if (this.rootContext) this.openEnded = true;
    if (!text) return;
    if (!this.whitespace) {
      this.column += 1;
      this.write(' ');
    }
    this.whitespace = false;
    this.indention = false;
    const points = Array.from(text);
    let spaces = false;
    let breaks = false;
    let start = 0;
    let end = 0;
    while (end <= points.length) {
      const ch = end < points.length ? points[end] : null;
      if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split) {
            this.writeIndent();
            this.whitespace = false;
            this.indention = false;
          } else {
            this.column += end - start;
            this.write(points.slice(start, end).join(''));
          }
          start = end;
        }
      } else if (breaks) {
        if (!isLineBreak(ch)) {
          if (points[start] === '\n') this.writeLineBreak();
          for (const br of points.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          this.whitespace = false;
          this.indention = false;
          start = end;
        }
      } else if (ch === null || ch === ' ' || isLineBreak(ch)) {
        this.column += end - start;
        this.write(points.slice(start, end).join(''));
        start = end;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = isLineBreak(ch);
      }
      end += 1;
    }
  }
}

