1	// The YAML emitter: a port of PyYAML's Emitter, keeping its column tracking,
2	// indentation rules, scalar styles and line-folding behaviour.
3	//
4	// PyYAML drives the writer from an event stream; because the node graph is
5	// already available here the same decisions are taken during a recursive walk.
6	// The state variables (column/whitespace/indention/indent stack/flow level and
7	// the *_context flags) are updated at exactly the same points.
8	
9	import { TAG } from './nodes.mjs';
10	import { analyzeScalar, isLineBreak } from './analysis.mjs';
11	import { resolveScalar } from './resolver.mjs';
12	
13	const ESCAPE_REPLACEMENTS = new Map([
14	  ['\0', '0'],
15	  ['\x07', 'a'],
16	  ['\b', 'b'],
17	  ['\t', 't'],
18	  ['\n', 'n'],
19	  ['\v', 'v'],
20	  ['\f', 'f'],
21	  ['\r', 'r'],
22	  ['\x1B', 'e'],
23	  ['"', '"'],
24	  ['\\', '\\'],
25	  ['\x85', 'N'],
26	  ['\xA0', '_'],
27	  ['\u2028', 'L'],
28	  ['\u2029', 'P'],
29	]);
30	
31	const DOUBLE_QUOTE_FORCED = '"\\\x85\u2028\u2029\uFEFF';
32	
33	// Characters that may appear unescaped in a tag suffix.
34	const TAG_SAFE = "-;/?:@&=+$,_.~*'()[]";
35	
36	function hexUpper(code, width) {
37	  let digits = code.toString(16).toUpperCase();
38	  while (digits.length < width) digits = '0' + digits;
39	  return digits;
40	}
41	
42	// '!!' handle for the standard tag prefix, verbatim form otherwise.
43	export function prepareTag(tag) {
44	  if (!tag) throw new Error('tag must not be empty');
45	  if (tag === '!') return tag;
46	  let handle = null;
47	  let suffix = tag;
48	  // sorted(tag_prefixes) == ['!', 'tag:yaml.org,2002:']; the last match wins.
49	  for (const [prefix, mapped] of [['!', '!'], ['tag:yaml.org,2002:', '!!']]) {
50	    if (tag.startsWith(prefix) && (prefix === '!' || prefix.length < tag.length)) {
51	      handle = mapped;
52	      suffix = tag.slice(prefix.length);
53	    }
54	  }
55	  let out = '';
56	  for (const ch of suffix) {
57	    const isAlphanumeric = (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z');
58	    if (isAlphanumeric || TAG_SAFE.indexOf(ch) >= 0 || (ch === '!' && handle !== '!')) {
59	      out += ch;
60	    } else {
61	      for (const byte of new TextEncoder().encode(ch)) out += '%' + hexUpper(byte, 2);
62	    }
63	  }
64	  return handle ? handle + out : '!<' + out + '>';
65	}
