67	export class Emitter {
68	  constructor(options) {
69	    const settings = options || {};
70	    this.chunks = [];
71	    this.column = 0;
72	    this.whitespace = true;
73	    this.indention = true;
74	    this.openEnded = false;
75	    this.indent = null;
76	    this.indents = [];
77	    this.flowLevel = 0;
78	    this.rootContext = false;
79	    this.sequenceContext = false;
80	    this.mappingContext = false;
81	    this.simpleKeyContext = false;
82	    this.canonical = settings.canonical === undefined ? false : settings.canonical;
83	    this.allowUnicode = settings.allowUnicode === undefined ? false : settings.allowUnicode;
84	    this.bestIndent = 2;
85	    if (settings.indent && settings.indent > 1 && settings.indent < 10) this.bestIndent = settings.indent;
86	    this.bestWidth = 80;
87	    if (settings.width && settings.width > this.bestIndent * 2) this.bestWidth = settings.width;
88	    this.analysis = null;
89	    this.style = null;
90	    this.preparedTag = null;
91	    this.preparedAnchor = null;
92	    this.serialized = new Set();
93	  }
94	
95	  // Emits a single implicit document, as yaml.dump() does with its defaults.
96	  emit(root) {
97	    this.expectNode(root, { root: true });
98	    this.writeIndent(); // DocumentEndEvent
99	    if (this.openEnded) { // StreamEndEvent
100	      this.writeIndicator('...', true);
101	      this.writeIndent();
102	    }
103	    return this.chunks.join('');
104	  }
105	
106	  // ------------------------------------------------------------- raw writing
107	
108	  write(data) { this.chunks.push(data); }
109	
110	  writeIndicator(indicator, needWhitespace, whitespace, indention) {
111	    const data = this.whitespace || !needWhitespace ? indicator : ' ' + indicator;
112	    this.whitespace = whitespace === true;
113	    this.indention = this.indention && indention === true;
114	    this.column += data.length;
115	    this.openEnded = false;
116	    this.write(data);
117	  }
118	
