121	    if (!this.indention || this.column > indent
122	        || (this.column === indent && !this.whitespace)) {
123	      this.writeLineBreak();
124	    }
125	    if (this.column < indent) {
126	      this.whitespace = true;
127	      this.write(' '.repeat(indent - this.column));
128	      this.column = indent;
129	    }
130	  }
131	
132	  writeLineBreak(data) {
133	    this.whitespace = true;
134	    this.indention = true;
135	    this.column = 0;
136	    this.write(data === undefined ? '\n' : data);
137	  }
