// yaml.dump() with PyYAML's defaults: Dumper, default_flow_style=False,
// sort_keys=True, allow_unicode=False, width=80, indent=2, no explicit
// document markers.

import { Representer } from './representer.mjs';
import { assignAnchors } from './serializer.mjs';
import { Emitter } from './emitter.mjs';

export function dump(value, options) {
  const settings = options || {};
  const representer = new Representer({
    defaultStyle: settings.defaultStyle,
    defaultFlowStyle: settings.defaultFlowStyle,
    sortKeys: settings.sortKeys,
  });
  const root = representer.represent(value);
  assignAnchors(root);
  const emitter = new Emitter({
    canonical: settings.canonical,
    allowUnicode: settings.allowUnicode,
    indent: settings.indent,
    width: settings.width,
  });
  return emitter.emit(root);
}

