// argparse derives this from os.path.basename(sys.argv[0]); the reference
// build reports "test2_executable", so diagnostics line up with it.
const PROG = 'test2_executable';

const USAGE = 'usage: ' + PROG + ' [-h] --a A';

const HELP = USAGE + '\n'
  + '\n'
  + 'options:\n'
  + '  -h, --help  show this help message and exit\n'
  + '  --a A\n';

class ArgumentError extends Error {}

// ^-\d+$|^-\d*\.\d+$
function looksLikeNegativeNumber(text) {
  if (text[0] !== '-') return false;
  let index = 1;
  let digits = 0;
  while (index < text.length && text[index] >= '0' && text[index] <= '9') { index++; digits++; }
  if (index === text.length) return digits > 0;
  if (text[index] !== '.') return false;
  index++;
  let decimals = 0;
  while (index < text.length && text[index] >= '0' && text[index] <= '9') { index++; decimals++; }
  return decimals > 0 && index === text.length;
}

export class ArgumentParser {
  constructor() {
    this.actions = [];
    this.optionStrings = new Map();
    this.addArgument(['-h', '--help'], { help: true });
  }

  addArgument(flags, options) {
    const settings = options || {};
    const action = {
      flags,
      dest: settings.dest || flags[flags.length - 1].replace('--', '').replace('-', ''),
      required: settings.required === true,
      help: settings.help === true,
      metavar: null,
    };
    action.metavar = action.dest.toUpperCase();
    this.actions.push(action);
    for (const flag of flags) this.optionStrings.set(flag, action);
    return action;
  }

