  // string should be treated as a positional.
  parseOptional(text) {
    if (!text) return null;
    if (text[0] !== '-') return null;
    if (this.optionStrings.has(text)) return [this.optionStrings.get(text), text, null];
    if (text.length === 1) return null;
    const equals = text.indexOf('=');
    if (equals >= 0) {
      const name = text.slice(0, equals);
      if (this.optionStrings.has(name)) {
        return [this.optionStrings.get(name), name, text.slice(equals + 1)];
      }
    }
    const matches = this.abbreviations(text);
    if (matches.length > 1) {
      throw new ArgumentError(
        'ambiguous option: ' + text + ' could match ' + matches.map((m) => m[1]).join(', '),
      );
