    if (matches.length === 1) return matches[0];
    if (looksLikeNegativeNumber(text)) return null;
    if (text.indexOf(' ') >= 0) return null;
    return [null, text, null];
  }

  abbreviations(text) {
    const equals = text.indexOf('=');
    const name = equals >= 0 ? text.slice(0, equals) : text;
    const explicit = equals >= 0 ? text.slice(equals + 1) : null;
    const found = [];
    if (!name.startsWith('--')) return found;
