  const out = streams && streams.out ? streams.out : (text) => process.stdout.write(text);
  const err = streams && streams.err ? streams.err : (text) => process.stderr.write(text);
  const parser = new ArgumentParser();
  parser.addArgument(['--a'], { required: true });
  let parsed;
  try {
    parsed = parser.parse(argv);
  } catch (error) {
    if (!(error instanceof ArgumentError)) throw error;
    err(USAGE + '\n');
    err(PROG + ': error: ' + error.message + '\n');
