#!/usr/bin/env node
// Differential harness: runs every expression in cases.txt through both the
// reference executable and test2.mjs, then reports any mismatch.
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const REFERENCE = '/workspace/dataset/test2_executable';
const CANDIDATE = '/output/test2.mjs';

const cases = readFileSync(process.argv[2] || '/output/tests/cases.txt', 'utf8')
  .split('\n')
  .filter((line) => line.length > 0 && !line.startsWith('#'))
  .map((line) => JSON_FREE_UNESCAPE(line));

// Cases are stored one per line with \n and \\ escaped.
function JSON_FREE_UNESCAPE(line) {
  let out = '';
  for (let i = 0; i < line.length; i++) {
    if (line[i] === '\\' && line[i + 1] === 'n') { out += '\n'; i++; }
    else if (line[i] === '\\' && line[i + 1] === 't') { out += '\t'; i++; }
    else if (line[i] === '\\' && line[i + 1] === '\\') { out += '\\'; i++; }
    else out += line[i];
  }
  return out;
}

let failures = 0;
for (const expression of cases) {
  const expected = spawnSync(REFERENCE, ['--a', expression], { encoding: 'utf8' });
  const actual = spawnSync('node', [CANDIDATE, '--a', expression], { encoding: 'utf8' });
  const sameOut = expected.stdout === actual.stdout;
  const sameCode = expected.status === actual.status;
  if (!sameOut || !sameCode) {
    failures++;
    process.stdout.write('MISMATCH: ' + expression + '\n');
    process.stdout.write('  reference (rc=' + expected.status + '): ' + show(expected.stdout) + '\n');
    process.stdout.write('  candidate (rc=' + actual.status + '): ' + show(actual.stdout) + '\n');
    if (actual.stderr && !sameOut) {
      process.stdout.write('  stderr: ' + actual.stderr.split('\n').slice(-3).join(' | ') + '\n');
    }
  }
}

function show(text) {
  return (text === undefined ? '<none>' : text)
    .split('\\').join('\\\\')
    .split('\n').join('\\n')
    .split('\t').join('\\t');
}

process.stdout.write((cases.length - failures) + '/' + cases.length + ' cases match\n');
process.exit(failures === 0 ? 0 : 1);

