// Tokeniser for the Python expression grammar accepted by eval().
// Hand written character scanning: no regular expressions anywhere.

import { syntaxError } from './errors.mjs';
import { PyBytes } from './values.mjs';

export const TOKEN = {
  NUMBER: 'NUMBER',
  STRING: 'STRING',
  BYTES: 'BYTES',
  FSTRING: 'FSTRING',
  NAME: 'NAME',
  OP: 'OP',
  EOF: 'EOF',
};

const SPACE = new Set([' ', '\t', '\f', '\v', '\r', '\n']);

const THREE_CHAR_OPS = new Set(['**=', '//=', '...', '<<=', '>>=']);
const TWO_CHAR_OPS = new Set([
  '**', '//', '<<', '>>', '<=', '>=', '==', '!=', '->', ':=',
  '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=', '@=',
]);
const ONE_CHAR_OPS = new Set([
  '+', '-', '*', '/', '%', '@', '&', '|', '^', '~', '<', '>',
  '(', ')', '[', ']', '{', '}', ',', ':', '.', ';', '=',
]);

const isDigit = (ch) => ch >= '0' && ch <= '9';
const isHex = (ch) => isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
const isOctal = (ch) => ch >= '0' && ch <= '7';

function isNameStart(ch) {
  if (ch === '_') return true;
  if (ch >= 'a' && ch <= 'z') return true;
  if (ch >= 'A' && ch <= 'Z') return true;
  return ch.codePointAt(0) > 0x7f; // treat any non-ASCII as an identifier char
}

const isNameChar = (ch) => isNameStart(ch) || isDigit(ch);

const STRING_PREFIXES = new Set(['r', 'b', 'u', 'f', 'rb', 'br', 'fr', 'rf']);

export class Tokenizer {
  constructor(source) {
    this.source = source;
    this.pos = 0;
    this.tokens = [];
  }

  error() { throw syntaxError('invalid syntax'); }

  peekChar(offset) { return this.source[this.pos + (offset || 0)]; }

  tokenize() {
    for (;;) {
      this.skipIgnorable();
      if (this.pos >= this.source.length) break;
      const start = this.pos;
      const ch = this.source[this.pos];

      if (isDigit(ch) || (ch === '.' && isDigit(this.peekChar(1)))) {
        this.tokens.push(this.readNumber());
      } else if (ch === '"' || ch === "'") {
        this.tokens.push(this.readString('', start));
      } else if (isNameStart(ch)) {
        const name = this.readName();
        const quote = this.source[this.pos];
        const lowered = name.toLowerCase();
        if ((quote === '"' || quote === "'") && STRING_PREFIXES.has(lowered)) {
          this.tokens.push(this.readString(lowered, start));
        } else {
          this.tokens.push({ type: TOKEN.NAME, value: name, start });
        }
      } else {
        this.tokens.push(this.readOperator(start));
      }
    }
    this.tokens.push({ type: TOKEN.EOF, value: '', start: this.pos });
    return this.tokens;
  }

  skipIgnorable() {
    while (this.pos < this.source.length) {
      const ch = this.source[this.pos];
      if (SPACE.has(ch)) {
        this.pos++;
      } else if (ch === '\\' && (this.source[this.pos + 1] === '\n' || this.source[this.pos + 1] === '\r')) {
        this.pos += 2;
      } else if (ch === '#') {
        while (this.pos < this.source.length && this.source[this.pos] !== '\n') this.pos++;
      } else {
        break;
      }
    }
  }

  readName() {
    const start = this.pos;
    while (this.pos < this.source.length && isNameChar(this.source[this.pos])) this.pos++;
    return this.source.slice(start, this.pos);
  }

  readOperator(start) {
    const three = this.source.slice(this.pos, this.pos + 3);
    if (THREE_CHAR_OPS.has(three)) {
      this.pos += 3;
      return { type: TOKEN.OP, value: three, start };
    }
    const two = this.source.slice(this.pos, this.pos + 2);
    if (TWO_CHAR_OPS.has(two)) {
      this.pos += 2;
      return { type: TOKEN.OP, value: two, start };
    }
    const one = this.source[this.pos];
    if (ONE_CHAR_OPS.has(one)) {
      this.pos++;
      return { type: TOKEN.OP, value: one, start };
    }
    this.error();
    return null;
  }

  // Integers (decimal/hex/octal/binary, with "_" separators), floats and
  // imaginary literals.
  readNumber() {
    const start = this.pos;
    const source = this.source;
    if (source[this.pos] === '0' && (source[this.pos + 1] === 'x' || source[this.pos + 1] === 'X')) {
      this.pos += 2;
      const digits = this.readDigits(isHex);
      return { type: TOKEN.NUMBER, value: BigInt('0x' + digits), start };
    }
    if (source[this.pos] === '0' && (source[this.pos + 1] === 'o' || source[this.pos + 1] === 'O')) {
      this.pos += 2;
      const digits = this.readDigits(isOctal);
      return { type: TOKEN.NUMBER, value: BigInt('0o' + digits), start };
    }
    if (source[this.pos] === '0' && (source[this.pos + 1] === 'b' || source[this.pos + 1] === 'B')) {
      this.pos += 2;
      const digits = this.readDigits((ch) => ch === '0' || ch === '1');
      return { type: TOKEN.NUMBER, value: BigInt('0b' + digits), start };
    }

    let text = this.readDigits(isDigit);
    let isFloatLiteral = false;
    if (source[this.pos] === '.') {
      isFloatLiteral = true;
      this.pos++;
      text += '.' + this.readDigits(isDigit);
    }
    if (source[this.pos] === 'e' || source[this.pos] === 'E') {
      const save = this.pos;
      let exponent = 'e';
      this.pos++;
      if (source[this.pos] === '+' || source[this.pos] === '-') {
        exponent += source[this.pos];
        this.pos++;
      }
      if (isDigit(source[this.pos])) {
        exponent += this.readDigits(isDigit);
        text += exponent;
        isFloatLiteral = true;
      } else {
        this.pos = save;
      }
    }
    if (source[this.pos] === 'j' || source[this.pos] === 'J') {
      this.pos++;
      return { type: TOKEN.NUMBER, value: Number(text), imaginary: true, start };
    }
    if (isFloatLiteral) return { type: TOKEN.NUMBER, value: Number(text), start };
    if (text.length > 1 && text[0] === '0') {
      // Python rejects leading zeros in decimal integers ("012").
      for (const ch of text) if (ch !== '0') this.error();
    }
    return { type: TOKEN.NUMBER, value: BigInt(text), start };
  }

  readDigits(accept) {
    let out = '';
    const source = this.source;
    while (this.pos < source.length) {
      const ch = source[this.pos];
      if (ch === '_') {
        this.pos++;
        continue;
      }
      if (!accept(ch)) break;
      out += ch;
      this.pos++;
    }
    if (!out) this.error();
    return out;
  }

  readString(prefix, start) {
    const quote = this.source[this.pos];
    let terminator = quote;
    if (this.source[this.pos + 1] === quote && this.source[this.pos + 2] === quote) {
      terminator = quote + quote + quote;
    }
    this.pos += terminator.length;
    const bodyStart = this.pos;
    for (;;) {
      if (this.pos >= this.source.length) this.error();
      const ch = this.source[this.pos];
      if (ch === '\\' && prefix.indexOf('r') < 0) {
        this.pos += 2;
        continue;
      }
      if (ch === '\\' && prefix.indexOf('r') >= 0) {
        this.pos += 2; // raw strings keep the backslash but it still escapes the quote
        continue;
      }
      if (this.source.startsWith(terminator, this.pos)) break;
      this.pos++;
    }
    const raw = this.source.slice(bodyStart, this.pos);
    this.pos += terminator.length;

    const isRaw = prefix.indexOf('r') >= 0;
    if (prefix.indexOf('f') >= 0) {
      return { type: TOKEN.FSTRING, value: raw, raw: isRaw, start };
    }
    if (prefix.indexOf('b') >= 0) {
      return { type: TOKEN.BYTES, value: new PyBytes(decodeBytes(raw, isRaw)), start };
    }
    return { type: TOKEN.STRING, value: isRaw ? raw : decodeEscapes(raw), start };
  }
}

const SIMPLE_ESCAPES = new Map([
  ['n', '\n'], ['t', '\t'], ['r', '\r'], ['\\', '\\'], ["'", "'"], ['"', '"'],
  ['a', '\x07'], ['b', '\b'], ['f', '\f'], ['v', '\v'], ['0', '\0'],
]);

// Interprets the escape sequences of a non-raw str literal.
export function decodeEscapes(raw) {
  let out = '';
  let i = 0;
  while (i < raw.length) {
    const ch = raw[i];
    if (ch !== '\\') {
      out += ch;
      i++;
      continue;
    }
    const next = raw[i + 1];
    if (next === undefined) throw syntaxError('EOL while scanning string literal');
    if (next === '\n') {
      i += 2;
      continue;
    }
    if (next === 'x' || next === 'u' || next === 'U') {
      const width = next === 'x' ? 2 : next === 'u' ? 4 : 8;
      const digits = raw.slice(i + 2, i + 2 + width);
      let valid = digits.length === width;
      if (valid) for (const digit of digits) if (!isHex(digit)) valid = false;
      if (!valid) throw syntaxError('truncated escape sequence');
      out += String.fromCodePoint(parseInt(digits, 16));
      i += 2 + width;
      continue;
    }
    if (isOctal(next)) {
      let digits = '';
      let j = i + 1;
      while (j < raw.length && digits.length < 3 && isOctal(raw[j])) {
        digits += raw[j];
        j++;
      }
      out += String.fromCharCode(parseInt(digits, 8));
      i = j;
      continue;
    }
    const simple = SIMPLE_ESCAPES.get(next);
    if (simple !== undefined) {
      out += simple;
      i += 2;
      continue;
    }
    out += ch + next; // unknown escapes stay verbatim, like CPython
    i += 2;
  }
  return out;
}

// bytes literals: every code unit must be < 256 once escapes are resolved.
function decodeBytes(raw, isRaw) {
  const text = isRaw ? raw : decodeEscapes(raw);
  const out = [];
  for (let i = 0; i < text.length; i++) {
    const code = text.charCodeAt(i);
    if (code > 0xff) {
      // Non-ASCII source characters are invalid in bytes literals; encode as
      // UTF-8 so we degrade gracefully instead of losing data.
      const encoded = new TextEncoder().encode(text[i]);
      for (const byte of encoded) out.push(byte);
    } else {
      out.push(code);
    }
  }
  return Uint8Array.from(out);
}

