#!/usr/bin/env node
// Generates a large corpus of Python expressions that stress the emitter's
// wrapping, quoting and indentation paths.  Written to stdout, one per line.

const out = [];
const push = (expression) => out.push(expression);

const words = ['a', 'bb', 'ccc', 'dddd', 'eeeee', 'ffffff', 'x', 'yy', 'zzz'];

// Plain / quoted scalars whose length crosses the 80 column boundary at
// several indentation levels.
for (let length = 70; length <= 95; length++) {
  let text = '';
  let index = 0;
  while (text.length < length) {
    text += (text ? ' ' : '') + words[index % words.length];
    index++;
  }
  text = text.slice(0, length);
  if (text.endsWith(' ')) text = text.slice(0, -1) + 'q';
  const quoted = "'" + text + "'";
  push(quoted);
  push('[' + quoted + ']');
  push('{"k": ' + quoted + '}');
  push('{"k": {"kk": ' + quoted + '}}');
  push('[[' + quoted + ']]');
  push("{'q" + text + "': 1}");
  push('[' + quoted + " + ':x'" + ']');
  push('["' + text + " #comment" + '"]');
  push('[' + '"' + text + '\\t' + '"' + ']'); // forces double quotes + folding
  push('[' + '"' + text.split(' ').join('  ') + '"' + ']');
}

// Words separated by long runs without spaces.
for (let length = 60; length <= 100; length += 7) {
  push("'" + 'z'.repeat(length) + " tail'");
  push("'head " + 'z'.repeat(length) + "'");
  push("['" + 'z'.repeat(length) + " middle tail']");
  push('{"key": "' + 'z'.repeat(length) + ' tail"}');
}

// Scalar resolution boundaries.
const scalars = [
  'y', 'Y', 'n', 'N', 'yes', 'YES', 'Yes', 'yEs', 'no', 'true', 'TRUE', 'off',
  'ON', 'null', 'NULL', 'Null', 'nULL', '~', '~x', '=', '==', '<<', '<<<',
  '0', '00', '007', '0o17', '0x1F', '0b101', '1_0', '-0', '+0', '1:30', '1:60',
  '.5', '0.5', '5.', '-.inf', '.INF', '.NaN', '.nan.', '1e5', '1e+5', '1.0e+5',
  '2001-12-14', '2001-12-14t21:59:43.10-05:00', '2001-12-14 21:59:43.10 -5',
  '2001-12-1', '20-12-14', '12345-12-14', '2001-12-14T21:59:43',
  '#', ' #', 'a #b', 'a#b', '-', '- ', '-a', '?', '?a', ': ', ':a', 'a:',
  'a: b', 'a:b:c', ',', 'a,b', '[', ']', '{', '}', '&a', '*a', '!a', '|a',
  '>a', '%a', '@a', '`a', '"a', "'a", '\\a', 'a\\b', 'a b', ' a', 'a ',
  '  ', '\\t', '\\n', '\\r', '\\x00', '\\x1b', '\\x85', '\\xa0', '\\u2028',
  '\\u2029', '\\ufeff', '\\u4f60', '\\U0001F600', 'e', 'E', 'e1', '.', '..',
  '...', '....', '---', '----', '--', 'a---', 'True', 'False', 'None',
];
for (const scalar of scalars) {
  const literal = "'" + scalar.split("'").join("\\'") + "'";
  push(literal);
  push('[' + literal + ']');
  push('{' + literal + ': 1}');
  push('{1: ' + literal + '}');
  push('{' + literal + ': ' + literal + '}');
  push('[[' + literal + ']]');
  push('(' + literal + ',)');
  push('{' + literal + ',}');
}

// Numbers.
const numbers = [
  '0', '-0', '1', '-1', '10**15', '10**16', '10**17', '2**53', '2**64',
  '0.0', '-0.0', '1.0', '0.5', '1e15', '1e16', '1e17', '1e-4', '1e-5',
  '1.7976931348623157e308', '5e-324', '1/3', '2/3', '1e100', '-1e100',
  "float('inf')", "float('-inf')", "float('nan')", '3.0', '100.0', '1e0',
  '123456789.123456789', '0.1', '0.2', '0.1+0.2', '10**308*10',
];
for (const number of numbers) {
  push(number);
  push('[' + number + ']');
  push('{"n": ' + number + '}');
  push('{' + number + ': "v"}');
}

// Structures.
push('{"a": [1, 2, {"b": [3, {"c": (4, 5)}]}], "d": {1, 2}}');
push('[{"x": [[{"y": ("z",)}]]}]');
push('{"t": ((1, 2), (3, (4, 5)))}');
push('{"s": {frozenset([1]), frozenset([2])}}');
push('{"empty": [[], {}, (), set(), "", None]}');
push('[b"abc", b"\\x00\\xff", b"a" * 60, b"a" * 200]');
push('{"bin": b"' + 'q'.repeat(120) + '"}');
push('[complex(1, 2), complex(0, 1), complex(1, 0), complex(-1.5, -2.5)]');
push('{"r": range(5), "f": frozenset([3, 1, 2])}');
push('dict((str(i), i) for i in range(30))');
push('[list(range(40))]');
push('{"k" + str(i): "v" * i for i in range(12)}');
push('[{"id": i, "name": "Item" + str(i)} for i in range(8)]');
push('{"level" + str(i): {"nested": [i] * i} for i in range(5)}');
push('[[[[[[[1]]]]]]]');
push('{"a": {"b": {"c": {"d": {"e": {"f": "g"}}}}}}');
push('[None] * 3 + [True, False] * 2');
push('{i: chr(65 + i) for i in range(26)}');
push('{"mixed": [1, "two", 3.0, True, None, (4,), {5: 6}, {7}]}');
push('sorted({"b": 1, "a": 2}.items())');
push('list({"a": 1, "b": 2}.items())');
push('{"tuple_key": {(1, 2): "a", (3, 4): "b"}}');
push('{(1, "x"): [1], (2, "y"): [2]}');
push('{frozenset([1, 2]): "fs"}');
push('{"self": [1, 2]} if False else {"other": [[3]] * 2}');
push('[{"shared": 1}] * 4');
push('{"a": ["x" * 100], "b": {"c": "y" * 100}}');
push('{"long": ["word " * 30, "word " * 40]}');
push('{"u": ["caf\\xe9", "\\u4f60\\u597d", "\\U0001F600"]}');
push('{"ctrl": ["a\\tb", "a\\nb", "a\\rb", "a\\x00b"]}');
push('[True, 1, 1.0, "1", None]');
push('{1: "int", 1.5: "float", "1": "str"}');
push('{0: "zero", False: "false"}');
push('{"": "", " ": " ", "  ": "  "}');
push('{"k": "v" * 200}');
push('{"k" * 200: "v"}');
push('{"k" * 127: 1}');
push('{"k" * 128: 1}');
push('{"k" * 129: 1}');

process.stdout.write(out.join('\n') + '\n');

